144	// ── 무기 (Mugi / UR) ──────────────────────────────────────────────────
145	export const MUGI_PARAMS = {
146	  harvestInterval:  400,   // 풍요의 비 발동 점수 간격
147	  harvestDuration:  5000,  // 풍요의 비 지속 시간 (ms)
148	  harvestSpawnMs:   800,   // 풍요의 비 중 금똥 소환 간격 (ms)
149	  harvestSpawnCount: 2,    // 소환 1회당 금똥 개수
150	} as const;
151	
