import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MUGI_PARAMS } from '../config/abilityParams';

// ── 용 비주얼 상수 ──────────────────────────────────────────────────
const DRAGON_DEPTH    = 95;
const DRAGON_NUM_SEGS = 34;
const DRAGON_ORBIT_R  = 62;       // 용 머리 공전 반경 (px)
const DRAGON_ORBIT_RY = 0.48;     // Y축 압축 (타원 궤도)
const DRAGON_ORBIT_SPEED = 2.1;   // rad/s
const DRAGON_TRAIL_STEP  = 3;     // trail 배열에서 세그먼트 간격
const DRAGON_TRAIL_LEN   = DRAGON_NUM_SEGS * DRAGON_TRAIL_STEP + 20;

interface YeoijuOrb {
  gfx: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
}

interface DragonSeg {
  gfx: Phaser.GameObjects.Graphics;
  baseAlpha: number;
  isHead: boolean;
}

export class MugiAbility extends BaseAbility {
  // ── 여의주 ──────────────────────────────────────────────────────────
  private lastYeoijuScore = 0;
  private yeoijuCount = 0;
  private yeoijus: YeoijuOrb[] = [];

  // ── 흑룡 ────────────────────────────────────────────────────────────
  private dragonActive  = false;
  private dragonAngle   = -Math.PI / 2; // 12시 방향부터 시작
  private dragonTrail:  { x: number; y: number }[] = [];
  private dragonSegs:   DragonSeg[] = [];
  private dragonBurnTimer = 0;

  // ── UI ──────────────────────────────────────────────────────────────
  private counterText: Phaser.GameObjects.Text | null = null;

  override onCreate(api: GameSceneAPI): void {
    // 씬 재시작 시 stale 상태 정리
    this.lastYeoijuScore = 0;
    this.yeoijuCount     = 0;
    this.yeoijus         = [];
    this.dragonActive    = false;
    this.dragonAngle     = -Math.PI / 2;
    this.dragonTrail     = [];
    this.dragonSegs      = [];
    this.dragonBurnTimer = 0;
    this.counterText     = null;

    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.dragonThreshold}`, {
      fontSize: '11px',
      color: '#ff6666',
      stroke: '#000000',
      strokeThickness: 3,
      lineSpacing: 2,
    }).setDepth(500).setAlpha(0.88);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
      this.lastYeoijuScore = score;
      this._spawnYeoiju(api);
    }
  }

  // ── 여의주 생성 ─────────────────────────────────────────────────────
  private _spawnYeoiju(api: GameSceneAPI): void {
    const scene = api.scene;
    const x = Phaser.Math.Between(30, 370);

    const gfx = scene.add.graphics().setDepth(150);
    // 외부 글로우
    gfx.fillStyle(0xff2222, 0.12);
    gfx.fillCircle(0, 0, 20);
    // 중간 레이어
    gfx.fillStyle(0xff2222, 0.38);
    gfx.fillCircle(0, 0, 13);
    // 중심 구슬
    gfx.fillStyle(0xff3333, 1);
    gfx.fillCircle(0, 0, 8);
    // 내부 밝은 코어
    gfx.fillStyle(0xff9999, 0.85);
    gfx.fillCircle(0, 0, 5);
    // 하이라이트
    gfx.fillStyle(0xffffff, 0.75);
    gfx.fillCircle(-2.5, -3, 2.2);
    gfx.setPosition(x, -20);

    // 펄스 애니메이션 (repeat: -1 → 수동으로 관리, destroy 시 자동 정리)
    scene.tweens.add({
      targets: gfx,
      alpha: { from: 0.72, to: 1 },
      yoyo: true,
      repeat: -1,
      duration: 720,
      ease: 'Sine.easeInOut',
    });

    this.yeoijus.push({ gfx, x, y: -20 });
  }

  // ── 매 프레임 ───────────────────────────────────────────────────────
  override onUpdate(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta * 0.001;
    this._updateYeoijus(api, delta);
    if (this.dragonActive) this._updateDragon(api, delta);
  }

  private _updateYeoijus(api: GameSceneAPI, delta: number): void {
    const { player } = api;
    const fallDelta = MUGI_PARAMS.yeoijuFallSpeed * delta;
    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
    const remaining: YeoijuOrb[] = [];

    for (const orb of this.yeoijus) {
      orb.y += fallDelta;
      orb.gfx.setPosition(orb.x, orb.y);

      const dx = player.x - orb.x;
      const dy = player.y - orb.y;
      if (dx * dx + dy * dy < r2) {
        this._collectYeoiju(orb, api);
        continue;
      }
      if (orb.y > 660) {
        orb.gfx.destroy();
        continue;
      }
      remaining.push(orb);
    }
    this.yeoijus = remaining;
  }

  // ── 여의주 수집 ─────────────────────────────────────────────────────
  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
    this._spawnCollectEffect(orb.x, orb.y, api.scene);
    orb.gfx.destroy();
    this.yeoijuCount++;
    this._updateCounter();

    if (this.yeoijuCount >= MUGI_PARAMS.dragonThreshold && !this.dragonActive) {
      this._activateDragon(api);
    }
  }

  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(160);
      g.fillStyle(0xff3333, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(200, 360),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  private _updateCounter(): void {
    if (!this.counterText) return;
    if (this.dragonActive) {
      this.counterText.setText('🐉 흑룡 소환!').setColor('#ff4400');
    } else {
      this.counterText.setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.dragonThreshold}`);
    }
  }

  // ── 흑룡 소환 ───────────────────────────────────────────────────────
  private _activateDragon(api: GameSceneAPI): void {
    const { scene, player } = api;
    this.dragonActive = true;

    scene.cameras.main.flash(450, 50, 0, 0, true);

    // 소환 폭발 이펙트
    for (let i = 0; i < 14; i++) {
      const angle = (i / 14) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(220);
      g.fillStyle(i % 2 === 0 ? 0xff2200 : 0x330000, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(4, 10));
      g.setPosition(player.x, player.y);
      scene.tweens.add({
        targets: g,
        x: player.x + Math.cos(angle) * Phaser.Math.Between(45, 100),
        y: player.y + Math.sin(angle) * Phaser.Math.Between(45, 100),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(380, 680),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }

    // 소환 텍스트
    const txt = scene.add.text(player.x, player.y - 55, '🐉 흑룡 소환!', {
      fontSize: '17px',
      fontFamily: 'Arial Black, sans-serif',
      color: '#ff4400',
      stroke: '#000000',
      strokeThickness: 5,
    }).setOrigin(0.5).setDepth(260);
    scene.tweens.add({
      targets: txt,
      y: txt.y - 65,
      alpha: 0,
      duration: 1600,
      ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });

    // trail 초기화 (플레이어 위치로 채우기)
    this.dragonTrail = Array.from({ length: DRAGON_TRAIL_LEN }, () => ({ x: player.x, y: player.y }));

    // 세그먼트 생성
    for (let i = 0; i < DRAGON_NUM_SEGS; i++) {
      const t    = i / (DRAGON_NUM_SEGS - 1);
      const size = Math.max(4, Math.round(14 - 10 * t));
      const isHead = i === 0;

      // 머리는 약간 더 밝은 검정, 몸통은 진한 검정
      const bodyColor = isHead ? 0x1a1a1a : 0x0d0d0d;
      const baseAlpha = isHead ? 0.96 : 0.88;

      const g = scene.add.graphics()
        .setDepth(DRAGON_DEPTH + (DRAGON_NUM_SEGS - i) * 0.01)
        .setAlpha(0);

      if (isHead) {
        this._drawDragonHead(g, size);
      } else {
        // 몸통 세그먼트
        g.fillStyle(bodyColor, 1);
        g.fillCircle(0, 0, size);
        // 비늘 하이라이트 (홀수 세그먼트마다)
        if (i % 3 === 1) {
          g.fillStyle(0x330000, 0.6);
          g.fillCircle(0, 0, size * 0.55);
        }
      }

      // 순차 등장 딜레이
      scene.tweens.add({
        targets: g,
        alpha: baseAlpha,
        delay: i * 22,
        duration: 280,
        ease: 'Quad.easeOut',
      });

      this.dragonSegs.push({ gfx: g, baseAlpha, isHead });
    }

    this._updateCounter();
  }

  private _drawDragonHead(g: Phaser.GameObjects.Graphics, size: number): void {
    // rotation=0 기준 오른쪽이 앞 → 용 머리 오른쪽에 눈/뿔
    // 몸통
    g.fillStyle(0x1a1a1a, 1);
    g.fillCircle(0, 0, size);
    // 이마 돌출
    g.fillStyle(0x222222, 1);
    g.fillEllipse(size * 0.35, 0, size * 0.9, size * 0.7);
    // 뿔 (위아래 대칭)
    g.lineStyle(2.5, 0x333333, 1);
    g.beginPath();
    g.moveTo(size * 0.2, -size * 0.75);
    g.lineTo(size * 0.55, -size * 1.45);
    g.strokePath();
    g.beginPath();
    g.moveTo(size * 0.2, size * 0.75);
    g.lineTo(size * 0.55, size * 1.45);
    g.strokePath();
    // 눈 (붉은색)
    g.fillStyle(0xff2222, 1);
    g.fillCircle(size * 0.45, -size * 0.35, 3.2);
    g.fillCircle(size * 0.45,  size * 0.35, 3.2);
    // 동공
    g.fillStyle(0x000000, 1);
    g.fillCircle(size * 0.55, -size * 0.35, 1.6);
    g.fillCircle(size * 0.55,  size * 0.35, 1.6);
    // 눈 하이라이트
    g.fillStyle(0xff8888, 0.7);
    g.fillCircle(size * 0.38, -size * 0.42, 1.2);
    g.fillCircle(size * 0.38,  size * 0.42, 1.2);
  }

  // ── 흑룡 매 프레임 업데이트 ─────────────────────────────────────────
  private _updateDragon(api: GameSceneAPI, delta: number): void {
    const { player, scene } = api;

    this.dragonAngle += DRAGON_ORBIT_SPEED * delta;

    const headX = player.x + Math.cos(this.dragonAngle) * DRAGON_ORBIT_R;
    const headY = player.y + Math.sin(this.dragonAngle) * DRAGON_ORBIT_R * DRAGON_ORBIT_RY - 8;

    this.dragonTrail.unshift({ x: headX, y: headY });
    if (this.dragonTrail.length > DRAGON_TRAIL_LEN) this.dragonTrail.pop();

    for (let i = 0; i < this.dragonSegs.length; i++) {
      const seg = this.dragonSegs[i];
      if (!seg || !seg.gfx.active) continue;

      const trailIdx = Math.min(i * DRAGON_TRAIL_STEP, this.dragonTrail.length - 1);
      const pos      = this.dragonTrail[trailIdx];
      if (!pos) continue;

      seg.gfx.setPosition(pos.x, pos.y);

      // 머리: 이동 방향으로 회전
      if (seg.isHead && trailIdx + 1 < this.dragonTrail.length) {
        const prev = this.dragonTrail[trailIdx + 1]!;
        const moveAngle = Math.atan2(pos.y - prev.y, pos.x - prev.x);
        seg.gfx.setRotation(moveAngle);
      }

      // 플레이어 앞에 있을 때 depth 높이기 (앞/뒤 원근감)
      const behindPlayer = pos.y > player.y;
      seg.gfx.setDepth(behindPlayer
        ? DRAGON_DEPTH + (DRAGON_NUM_SEGS - i) * 0.01
        : DRAGON_DEPTH + 10 + (DRAGON_NUM_SEGS - i) * 0.01);
    }

    // 소각 타이머
    this.dragonBurnTimer += scene.game.loop.delta;
    if (this.dragonBurnTimer >= MUGI_PARAMS.dragonBurnInterval) {
      this.dragonBurnTimer = 0;
      this._burnNearby(api);
    }
  }

  // ── 소각 처리 ───────────────────────────────────────────────────────
  private _burnNearby(api: GameSceneAPI): void {
    const { scene } = api;
    const head = this.dragonTrail[0];
    if (!head) return;

    const r2 = MUGI_PARAMS.dragonBurnRadius ** 2;

    (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => {
        if (!p.active) return false;
        const dx = p.x - head.x;
        const dy = p.y - head.y;
        return dx * dx + dy * dy <= r2;
      })
      .forEach(p => {
        this._spawnBurnEffect(p.x, p.y, scene);
        (p as unknown as PoolablePoopBase).recycle();
        api.addAbilityBonus(3);
      });
  }

  private _spawnBurnEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 5; i++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(210);
      g.fillStyle(i % 2 === 0 ? 0xff2200 : 0x880000, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 5));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(8, 20),
        y: y + Math.sin(angle) * Phaser.Math.Between(8, 20) - 12,
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(140, 240),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  // ── 정리 ────────────────────────────────────────────────────────────
  override onDestroy(_api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.dragonSegs.forEach(s => s.gfx.destroy());
    this.dragonSegs = [];
    this.dragonTrail = [];
    this.counterText?.destroy();
    this.counterText = null;
  }
}

