        seg.gfx.setRotation(moveAngle);
      }

      // 플레이어 앞에 있을 때 depth 높이기 (앞/뒤 원근감)
      const behindPlayer = pos.y > player.y;
      seg.gfx.setDepth(behindPlayer
        ? DRAGON_DEPTH + (DRAGON_NUM_SEGS - i) * 0.01
        : DRAGON_DEPTH + 10 + (DRAGON_NUM_SEGS - i) * 0.01);
    }

    // 소각 타이머
    this.dragonBurnTimer += scene.game.loop.delta;
    if (this.dragonBurnTimer >= MUGI_PARAMS.dragonBurnInterval) {
      this.dragonBurnTimer = 0;
      this._burnNearby(api);
    }
  }

  // ── 소각 처리 ───────────────────────────────────────────────────────
  private _burnNearby(api: GameSceneAPI): void {
    const { scene } = api;
    const head = this.dragonTrail[0];
    if (!head) return;

    const r2 = MUGI_PARAMS.dragonBurnRadius ** 2;

    (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => {
        if (!p.active) return false;
        const dx = p.x - head.x;
        const dy = p.y - head.y;
        return dx * dx + dy * dy <= r2;
      })
      .forEach(p => {
        this._spawnBurnEffect(p.x, p.y, scene);
        (p as unknown as PoolablePoopBase).recycle();
        api.addAbilityBonus(3);
      });
  }

  private _spawnBurnEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 5; i++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(210);
      g.fillStyle(i % 2 === 0 ? 0xff2200 : 0x880000, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 5));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(8, 20),
        y: y + Math.sin(angle) * Phaser.Math.Between(8, 20) - 12,
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(140, 240),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  // ── 정리 ────────────────────────────────────────────────────────────
  override onDestroy(_api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.dragonSegs.forEach(s => s.gfx.destroy());
    this.dragonSegs = [];
    this.dragonTrail = [];
    this.counterText?.destroy();
    this.counterText = null;
  }
}

