  yeoijuCollectRadius: 28,    // 여의주 수집 반경 (px)
  dragonThreshold:     3,     // 흑룡 발동 여의주 수집 수 (테스트: 3)
  dragonBurnRadius:    68,    // 흑룡 소각 판정 반경 (px)
