          onComplete: () => g.destroy(),
        });
      }
    });

    // 600ms 후: 꽃잎 터짐 + 화면 전체 똥 제거
    scene.time.delayedCall(600, () => {
      if (!scene.sys.isActive()) return;

      petals.forEach((g, i) => {
        const angle = (i / PETAL_COUNT) * Math.PI * 2;
        scene.tweens.add({
          targets: g,
          x: cx + Math.cos(angle) * 90,
          y: cy + Math.sin(angle) * 90,
          alpha: 0,
          scale: 0.25,
          duration: 420,
          ease: 'Quad.easeOut',
          onComplete: () => g.destroy(),
        });
      });

      scene.tweens.add({
        targets: centerGlow,
        alpha: 0,
        scale: 2.8,
        duration: 420,
        ease: 'Quad.easeOut',
        onComplete: () => centerGlow.destroy(),
      });

      this._clearAllPoops(api);
    });

    this._updateCounter();
  }

  // ── 화면 전체 일반 똥 제거 ─────────────────────────────────────────
  private _clearAllPoops(api: GameSceneAPI): void {
    const { poops, player, scene } = api;
    let cleared = 0;

    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active)
      .forEach(p => {
        this._spawnPetalEffect(p.x, p.y, scene);
        (p as unknown as PoolablePoopBase).recycle();
        cleared++;
      });

    if (cleared === 0) return;

    const bonus = cleared * MUGI_PARAMS.lotusPoopBonus;
    api.addAbilityBonus(bonus);

    const txt = scene.add.text(player.x, player.y - 35, `+${bonus}`, {
      fontSize: '19px',
      fontFamily: 'Arial Black, sans-serif',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 4,
    }).setOrigin(0.5).setDepth(250);
    scene.tweens.add({
      targets: txt,
      y: txt.y - 52,
      alpha: 0,
      duration: 950,
      ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });
  }

  private _spawnPetalEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 3; i++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(205);
      g.fillStyle(0xff88cc, 1);
      g.fillEllipse(0, 0, 6, 11);
      g.setPosition(x, y).setRotation(angle);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(10, 24),
        y: y + Math.sin(angle) * Phaser.Math.Between(10, 24),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(180, 320),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  // ── 정리 ────────────────────────────────────────────────────────────
  override onDestroy(_api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.destroy();
    this.counterText = null;
  }
}

