import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MUGI_PARAMS } from '../config/abilityParams';

const PETAL_COUNT = 8;
const PETAL_R     = 30; // 꽃잎 배치 반경 (px)

interface YeoijuOrb {
  gfx: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
}

export class MugiAbility extends BaseAbility {
  // ── 여의주 ──────────────────────────────────────────────────────────
  private lastYeoijuScore = 0;
  private yeoijuCount     = 0;
  private yeoijus: YeoijuOrb[] = [];

  // ── UI ──────────────────────────────────────────────────────────────
  private counterText: Phaser.GameObjects.Text | null = null;

  override onCreate(api: GameSceneAPI): void {
    this.lastYeoijuScore = 0;
    this.yeoijuCount     = 0;
    this.yeoijus         = [];
    this.counterText     = null;

    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.lotusThreshold}`, {
      fontSize: '11px',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 3,
    }).setDepth(500).setAlpha(0.88);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
      this.lastYeoijuScore = score;
      this._spawnYeoiju(api);
    }
  }

  // ── 여의주 생성 ─────────────────────────────────────────────────────
  private _spawnYeoiju(api: GameSceneAPI): void {
    const scene = api.scene;
    const x = Phaser.Math.Between(30, 370);

    const gfx = scene.add.graphics().setDepth(150);
    gfx.fillStyle(0xff2222, 0.12);
    gfx.fillCircle(0, 0, 20);
    gfx.fillStyle(0xff2222, 0.38);
    gfx.fillCircle(0, 0, 13);
    gfx.fillStyle(0xff3333, 1);
    gfx.fillCircle(0, 0, 8);
    gfx.fillStyle(0xff9999, 0.85);
    gfx.fillCircle(0, 0, 5);
    gfx.fillStyle(0xffffff, 0.75);
    gfx.fillCircle(-2.5, -3, 2.2);
    gfx.setPosition(x, -20);

    scene.tweens.add({
      targets: gfx,
      alpha: { from: 0.72, to: 1 },
      yoyo: true,
      repeat: -1,
      duration: 720,
      ease: 'Sine.easeInOut',
    });

    this.yeoijus.push({ gfx, x, y: -20 });
  }

  // ── 매 프레임 ───────────────────────────────────────────────────────
  override onUpdate(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta * 0.001;
    const { player } = api;
    const fallDelta = MUGI_PARAMS.yeoijuFallSpeed * delta;
    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
    const remaining: YeoijuOrb[] = [];

    for (const orb of this.yeoijus) {
      orb.y += fallDelta;
      orb.gfx.setPosition(orb.x, orb.y);

      const dx = player.x - orb.x;
      const dy = player.y - orb.y;
      if (dx * dx + dy * dy < r2) {
        this._collectYeoiju(orb, api);
        continue;
      }
      if (orb.y > 660) {
        orb.gfx.destroy();
        continue;
      }
      remaining.push(orb);
    }
    this.yeoijus = remaining;
  }

  // ── 여의주 수집 ─────────────────────────────────────────────────────
  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
    this._spawnCollectEffect(orb.x, orb.y, api.scene);
    orb.gfx.destroy();
    this.yeoijuCount++;
    this._updateCounter();

    if (this.yeoijuCount >= MUGI_PARAMS.lotusThreshold) {
      this.yeoijuCount = 0;
      this._activateLotus(api);
    }
  }

  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(160);
      g.fillStyle(0xff3333, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(200, 360),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  private _updateCounter(): void {
    if (!this.counterText) return;
    this.counterText
      .setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.lotusThreshold}`)
      .setColor('#ff88cc');
  }

  // ── 연화 소환 ───────────────────────────────────────────────────────
  private _activateLotus(api: GameSceneAPI): void {
    const { scene, player } = api;
    const cx = player.x;
    const cy = player.y;

    scene.cameras.main.flash(280, 255, 180, 210, true);

    // 소환 텍스트
    const txt = scene.add.text(cx, cy - 58, '🌸 연화 청정!', {
      fontSize: '17px',
      fontFamily: 'Arial Black, sans-serif',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 5,
    }).setOrigin(0.5).setDepth(260);
    scene.tweens.add({
      targets: txt,
      y: txt.y - 62,
      alpha: 0,
      duration: 1500,
      ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });

    // 중앙 글로우
    const centerGlow = scene.add.graphics().setDepth(200);
    centerGlow.fillStyle(0xff88cc, 0.35);
    centerGlow.fillCircle(0, 0, 38);
    centerGlow.fillStyle(0xffddee, 0.65);
    centerGlow.fillCircle(0, 0, 20);
    centerGlow.fillStyle(0xffffff, 0.9);
    centerGlow.fillCircle(0, 0, 9);
    centerGlow.setPosition(cx, cy).setScale(0);
    scene.tweens.add({
      targets: centerGlow,
      scale: 1,
      duration: 360,
      ease: 'Back.easeOut',
    });

    // 꽃잎 8개 등장
    const petals: Phaser.GameObjects.Graphics[] = [];
    for (let i = 0; i < PETAL_COUNT; i++) {
      const angle = (i / PETAL_COUNT) * Math.PI * 2;
      const px    = cx + Math.cos(angle) * PETAL_R;
      const py    = cy + Math.sin(angle) * PETAL_R;

      const g = scene.add.graphics().setDepth(201);
      // 바깥 꽃잎
      g.fillStyle(0xff88cc, 0.92);
      g.fillEllipse(0, 0, 11, 24);
      // 내부 밝은 결
      g.fillStyle(0xffbbdd, 0.75);
      g.fillEllipse(0, -3, 6, 14);
      // 끝 부분 살짝 밝게
      g.fillStyle(0xffffff, 0.35);
      g.fillEllipse(0, -7, 4, 6);

      g.setPosition(px, py)
       .setRotation(angle + Math.PI / 2) // 꽃잎이 중앙을 향하도록
       .setScale(0);

      scene.tweens.add({
        targets: g,
        scale: 1,
        delay: i * 35,
        duration: 260,
        ease: 'Back.easeOut',
      });
      petals.push(g);
    }

    // 500ms 후: 수술 파티클 등장
    scene.time.delayedCall(500, () => {
      if (!scene.sys.isActive()) return;
      for (let j = 0; j < 12; j++) {
        const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
        const g = scene.add.graphics().setDepth(202);
        g.fillStyle(0xffdd44, 1);
        g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
        g.setPosition(cx, cy);
        scene.tweens.add({
          targets: g,
          x: cx + Math.cos(angle) * Phaser.Math.Between(14, 38),
          y: cy + Math.sin(angle) * Phaser.Math.Between(14, 38),
          alpha: 0, scale: 0,
          duration: Phaser.Math.Between(300, 450),
          ease: 'Quad.easeOut',
          onComplete: () => g.destroy(),
        });
      }
    });

    // 600ms 후: 꽃잎 터짐 + 화면 전체 똥 제거
    scene.time.delayedCall(600, () => {
      if (!scene.sys.isActive()) return;

      petals.forEach((g, i) => {
        const angle = (i / PETAL_COUNT) * Math.PI * 2;
        scene.tweens.add({
          targets: g,
          x: cx + Math.cos(angle) * 90,
          y: cy + Math.sin(angle) * 90,
          alpha: 0,
          scale: 0.25,
          duration: 420,
          ease: 'Quad.easeOut',
          onComplete: () => g.destroy(),
        });
      });

      scene.tweens.add({
