// ── 연화 소환 (옆면 연꽃) ───────────────────────────────────────────
private _activateLotus(api: GameSceneAPI): void {
  const { scene, player } = api;
  const cx = player.x;
  const cy = player.y - 5; // 플레이어 중심보다 살짝 위

  scene.cameras.main.flash(280, 255, 240, 210, true);

  // 소환 텍스트
  const txt = scene.add.text(cx, cy - 62, '🌸 연화 청정!', {
    fontSize: '17px',
    fontFamily: 'Arial Black, sans-serif',
    color: '#fffde7',
    stroke: '#000000',
    strokeThickness: 5,
  }).setOrigin(0.5).setDepth(260);
  scene.tweens.add({
    targets: txt, y: txt.y - 60, alpha: 0,
    duration: 1500, ease: 'Quad.easeOut',
    onComplete: () => txt.destroy(),
  });

  // ── 꽃받침 (연두색 타원) ──────────────────────────────────────────
  const base = scene.add.graphics().setDepth(196).setScale(0);
  base.fillStyle(0x66bb6a, 0.85);
  base.fillEllipse(0, 0, 28, 9);
  base.fillStyle(0x81c784, 0.6);
  base.fillEllipse(0, -2, 16, 5);
  base.setPosition(cx, cy + 2);
  scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });

  // ── 금빛 중앙 글로우 ──────────────────────────────────────────────
  const glow = scene.add.graphics().setDepth(197).setScale(0);
  glow.fillStyle(0xffd700, 0.20);
  glow.fillCircle(0, 0, 30);
  glow.fillStyle(0xffe082, 0.35);
  glow.fillCircle(0, 0, 18);
  glow.fillStyle(0xffffff, 0.55);
  glow.fillCircle(0, 0, 8);
  glow.setPosition(cx, cy - 14);
  scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });

  // ── 꽃잎 생성: 바닥 한 점에서 각도별로 펼쳐짐 ────────────────────
  // 중심 좌표 = (cx + sin(rot) * h/2, cy - cos(rot) * h/2)
  const petals: { gfx: Phaser.GameObjects.Graphics; rotRad: number }[] = [];

  LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
    const rotRad = rotDeg * Math.PI / 180;
    // 꽃잎 바닥을 (cx, cy+2)에 맞추기 위한 중심 좌표
    const px = cx + Math.sin(rotRad) * (h / 2);
    const py = (cy + 2) - Math.cos(rotRad) * (h / 2);

    const g = scene.add.graphics().setDepth(197 + depthOff);

    // 꽃잎 본체 (흰/크림)
    g.fillStyle(color, 0.92);
    g.fillEllipse(0, 0, w, h);
    // 중앙 세로 밝은 결
    g.fillStyle(0xffffff, 0.45);
    g.fillEllipse(0, 0, w * 0.35, h * 0.65);
    // 끝부분 금빛 테두리 느낌
    g.fillStyle(0xffd700, 0.18);
    g.fillEllipse(0, -(h * 0.3), w * 0.55, h * 0.22);
    // 꽃잎 가장자리 연핑크
    g.lineStyle(1, 0xffc0d0, 0.4);
    g.strokeEllipse(0, 0, w, h);

    g.setPosition(px, py).setRotation(rotRad).setScale(0);

    // 바깥 꽃잎부터 안쪽 순으로 등장 (외층이 먼저 펼쳐짐)
    const delay = idx * 40;
    scene.tweens.add({
      targets: g, scale: 1,
      delay, duration: 280,
      ease: 'Back.easeOut',
    });

    petals.push({ gfx: g, rotRad });
  });

  // ── 수술 (stamen): 중앙 금빛 구슬 ──────────────────────────────
  const stamen = scene.add.graphics().setDepth(203).setScale(0);
  stamen.fillStyle(0xffd700, 1);
  stamen.fillCircle(0, 0, 5);
  stamen.fillStyle(0xffff99, 0.9);
  stamen.fillCircle(0, 0, 3);
  stamen.fillStyle(0xffffff, 0.7);
  stamen.fillCircle(-1, -1.5, 1.5);
  stamen.setPosition(cx, cy - 20);
  scene.tweens.add({
    targets: stamen, scale: 1,
    delay: LOTUS_DEFS.length * 40 - 20,
    duration: 220, ease: 'Back.easeOut',
  });

  // ── 550ms 후: 수술 주변 금빛 파티클 ─────────────────────────────
  scene.time.delayedCall(550, () => {
    if (!scene.sys.isActive()) return;
    for (let j = 0; j < 10; j++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(204);
      g.fillStyle(0xffd700, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 3));
      g.setPosition(cx, cy - 20);
      scene.tweens.add({
        targets: g,
        x: cx + Math.cos(angle) * Phaser.Math.Between(12, 30),
        y: (cy - 20) + Math.sin(angle) * Phaser.Math.Between(8, 22),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(280, 420),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  });

  // ── 680ms 후: 꽃잎 비산 + 전체 똥 제거 ──────────────────────────
  scene.time.delayedCall(680, () => {
    if (!scene.sys.isActive()) return;

    petals.forEach(({ gfx, rotRad }) => {
      // 각 꽃잎은 자신의 기울기 방향으로 날아감
      scene.tweens.add({
        targets: gfx,
        x: gfx.x + Math.sin(rotRad) * 70,
        y: gfx.y - Math.cos(rotRad) * 70,
        alpha: 0, scale: 0.2, rotation: gfx.rotation + Phaser.Math.FloatBetween(-0.6, 0.6),
        duration: 400, ease: 'Quad.easeOut',
        onComplete: () => gfx.destroy(),
      });
    });

    [glow, base, stamen].forEach(obj => {
      scene.tweens.add({
        targets: obj, alpha: 0, scale: obj === glow ? 2.5 : 0,
        duration: 380, ease: 'Quad.easeOut',
        onComplete: () => obj.destroy(),
      });
    });

    this._clearAllPoops(api);
  });

  this._updateCounter();
}

