    g.fillEllipse(0, -(h * 0.3), w * 0.55, h * 0.22);
    // 꽃잎 가장자리 연핑크
    g.lineStyle(1, 0xffc0d0, 0.4);
    g.strokeEllipse(0, 0, w, h);

    g.setPosition(px, py).setRotation(rotRad).setScale(0);

    // 바깥 꽃잎부터 안쪽 순으로 등장 (외층이 먼저 펼쳐짐)
    const delay = idx * 40;
    scene.tweens.add({
      targets: g, scale: 1,
      delay, duration: 280,
      ease: 'Back.easeOut',
    });

    petals.push({ gfx: g, rotRad });
  });

  // ── 수술 (stamen): 중앙 금빛 구슬 ──────────────────────────────
  const stamen = scene.add.graphics().setDepth(203).setScale(0);
  stamen.fillStyle(0xffd700, 1);
  stamen.fillCircle(0, 0, 5);
  stamen.fillStyle(0xffff99, 0.9);
  stamen.fillCircle(0, 0, 3);
  stamen.fillStyle(0xffffff, 0.7);
  stamen.fillCircle(-1, -1.5, 1.5);
  stamen.setPosition(cx, cy - 20);
  scene.tweens.add({
    targets: stamen, scale: 1,
    delay: LOTUS_DEFS.length * 40 - 20,
    duration: 220, ease: 'Back.easeOut',
  });

  // ── 550ms 후: 수술 주변 금빛 파티클 ─────────────────────────────
  scene.time.delayedCall(550, () => {
    if (!scene.sys.isActive()) return;
    for (let j = 0; j < 10; j++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(204);
      g.fillStyle(0xffd700, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 3));
      g.setPosition(cx, cy - 20);
      scene.tweens.add({
        targets: g,
        x: cx + Math.cos(angle) * Phaser.Math.Between(12, 30),
        y: (cy - 20) + Math.sin(angle) * Phaser.Math.Between(8, 22),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(280, 420),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  });

  // ── 680ms 후: 꽃잎 비산 + 전체 똥 제거 ──────────────────────────
  scene.time.delayedCall(680, () => {
    if (!scene.sys.isActive()) return;

    petals.forEach(({ gfx, rotRad }) => {
      // 각 꽃잎은 자신의 기울기 방향으로 날아감
      scene.tweens.add({
        targets: gfx,
        x: gfx.x + Math.sin(rotRad) * 70,
        y: gfx.y - Math.cos(rotRad) * 70,
        alpha: 0, scale: 0.2, rotation: gfx.rotation + Phaser.Math.FloatBetween(-0.6, 0.6),
        duration: 400, ease: 'Quad.easeOut',
        onComplete: () => gfx.destroy(),
      });
    });

    [glow, base, stamen].forEach(obj => {
      scene.tweens.add({
        targets: obj, alpha: 0, scale: obj === glow ? 2.5 : 0,
        duration: 380, ease: 'Quad.easeOut',
        onComplete: () => obj.destroy(),
      });
    });

    this._clearAllPoops(api);
  });

  this._updateCounter();
}

