/** P<1 일수록 끝이 더 날카로워짐 (0.5 = 침형, 1.0 = 타원) */
private _petalPoints(w: number, h: number, P = 0.52): { x: number; y: number }[] {
  const N = 26;
  const pts: { x: number; y: number }[] = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    pts.push({ x:  (w / 2) * Math.pow(Math.sin(t * Math.PI), P), y: -h / 2 + t * h });
  }
  for (let i = N - 1; i >= 0; i--) {
    const t = i / N;
    pts.push({ x: -(w / 2) * Math.pow(Math.sin(t * Math.PI), P), y: -h / 2 + t * h });
  }
  return pts;
}

private _drawPetalShape(g: Phaser.GameObjects.Graphics, w: number, h: number, color: number): void {
  // 본체
  g.fillStyle(color, 0.92);
  g.fillPoints(this._petalPoints(w, h), true);

  // 중앙 세로 결 (밝은 흰색)
  g.fillStyle(0xffffff, 0.48);
  g.fillPoints(this._petalPoints(w * 0.32, h * 0.72, 0.6)
    .map(p => ({ x: p.x, y: p.y - h * 0.04 })), true);

  // 끝부분 금빛 광택
  g.fillStyle(0xffd700, 0.16);
  g.fillPoints(this._petalPoints(w * 0.5, h * 0.24, 0.7)
    .map(p => ({ x: p.x, y: p.y - h * 0.36 })), true);

  // 가장자리 연핑크 선
  g.lineStyle(1, 0xffb3c6, 0.38);
  g.strokePoints(this._petalPoints(w, h), true);
}

