22	  // ── 내층 ──
23	  [ -24,     17,  54,  0xffffff,    3 ],
24	  [  24,     17,  54,  0xffffff,    3 ],
25	  [ -11,     15,  50,  0xffffff,    3 ],
26	  [  11,     15,  50,  0xffffff,    3 ],
27	  // ── 중앙 ──
28	  [   0,     13,  44,  0xffffff,    4 ],
29	];
30	
31	interface YeoijuOrb {
32	  gfx: Phaser.GameObjects.Graphics;
33	  x: number;
34	  y: number;
35	}
36	
37	export class MugiAbility extends BaseAbility {
38	  // ── 여의주 ──────────────────────────────────────────────────────────
39	  private lastYeoijuScore = 0;
40	  private yeoijuCount     = 0;
41	  private yeoijus: YeoijuOrb[] = [];
42	
43	  // ── UI ──────────────────────────────────────────────────────────────
44	  private counterText: Phaser.GameObjects.Text | null = null;
45	
46	  override onCreate(api: GameSceneAPI): void {
47	    this.lastYeoijuScore = 0;
48	    this.yeoijuCount     = 0;
49	    this.yeoijus         = [];
50	    this.counterText     = null;
51	
52	    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.lotusThreshold}`, {
53	      fontSize: '11px',
54	      color: '#ff88cc',
55	      stroke: '#000000',
56	      strokeThickness: 3,
57	    }).setDepth(500).setAlpha(0.88);
58	  }
59	
60	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
61	    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
62	      this.lastYeoijuScore = score;
63	      this._spawnYeoiju(api);
64	    }
65	  }
66	
67	  // ── 여의주 생성 ─────────────────────────────────────────────────────
68	  private _spawnYeoiju(api: GameSceneAPI): void {
69	    const scene = api.scene;
70	    const x = Phaser.Math.Between(30, 370);
71	
72	    const gfx = scene.add.graphics().setDepth(150);
73	    gfx.fillStyle(0xff2222, 0.12);
74	    gfx.fillCircle(0, 0, 20);
75	    gfx.fillStyle(0xff2222, 0.38);
76	    gfx.fillCircle(0, 0, 13);
77	    gfx.fillStyle(0xff3333, 1);
78	    gfx.fillCircle(0, 0, 8);
79	    gfx.fillStyle(0xff9999, 0.85);
80	    gfx.fillCircle(0, 0, 5);
81	    gfx.fillStyle(0xffffff, 0.75);
82	    gfx.fillCircle(-2.5, -3, 2.2);
83	    gfx.setPosition(x, -20);
84	
85	    scene.tweens.add({
86	      targets: gfx,
87	      alpha: { from: 0.72, to: 1 },
88	      yoyo: true,
89	      repeat: -1,
90	      duration: 720,
91	      ease: 'Sine.easeInOut',
92	    });
93	
94	    this.yeoijus.push({ gfx, x, y: -20 });
95	  }
96	
97	  // ── 매 프레임 ───────────────────────────────────────────────────────
98	  override onUpdate(api: GameSceneAPI): void {
99	    const delta = api.scene.game.loop.delta * 0.001;
100	    const { player } = api;
101	    const fallSpeed = api.baseSpeed + api.difficultyLevel * 40;
102	    const fallDelta = fallSpeed * delta;
103	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
104	    const remaining: YeoijuOrb[] = [];
105	
106	    for (const orb of this.yeoijus) {
107	      orb.y += fallDelta;
108	      orb.gfx.setPosition(orb.x, orb.y);
109	
110	      const dx = player.x - orb.x;
111	      const dy = player.y - orb.y;
112	      if (dx * dx + dy * dy < r2) {
113	        this._collectYeoiju(orb, api);
114	        continue;
115	      }
116	      if (orb.y > 660) {
117	        orb.gfx.destroy();
118	        continue;
119	      }
120	      remaining.push(orb);
121	    }
122	    this.yeoijus = remaining;
123	  }
124	
125	  // ── 여의주 수집 ─────────────────────────────────────────────────────
126	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
127	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
128	    orb.gfx.destroy();
129	    this.yeoijuCount++;
130	    this._updateCounter();
131	
132	    if (this.yeoijuCount >= MUGI_PARAMS.lotusThreshold) {
133	      this.yeoijuCount = 0;
134	      this._activateLotus(api);
135	    }
136	  }
137	
138	  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
139	    for (let i = 0; i < 6; i++) {
140	      const angle = (i / 6) * Math.PI * 2;
141	      const g = scene.add.graphics().setDepth(160);
142	      g.fillStyle(0xff3333, 1);
143	      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
144	      g.setPosition(x, y);
145	      scene.tweens.add({
146	        targets: g,
147	        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
148	        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
149	        alpha: 0, scale: 0,
150	        duration: Phaser.Math.Between(200, 360),
151	        ease: 'Quad.easeOut',
152	        onComplete: () => g.destroy(),
153	      });
154	    }
155	  }
156	
157	  private _updateCounter(): void {
158	    if (!this.counterText) return;
159	    this.counterText
160	      .setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.lotusThreshold}`)
161	      .setColor('#ff88cc');
162	  }
163	
164	  // ── 연화 소환 (옆면 연꽃) ───────────────────────────────────────────
165	  private _activateLotus(api: GameSceneAPI): void {
166	    const { scene, player } = api;
167	    const cx = player.x;
168	    const cy = player.y - 5; // 플레이어 중심보다 살짝 위
169	
170	    scene.cameras.main.flash(280, 255, 240, 210, true);
171	
172	    // 소환 텍스트
173	    const txt = scene.add.text(cx, cy - 92, '🌸 연화 청정!', {
174	      fontSize: '17px',
175	      fontFamily: 'Arial Black, sans-serif',
176	      color: '#fffde7',
177	      stroke: '#000000',
178	      strokeThickness: 5,
179	    }).setOrigin(0.5).setDepth(260);
180	    scene.tweens.add({
181	      targets: txt, y: txt.y - 60, alpha: 0,
182	      duration: 1500, ease: 'Quad.easeOut',
183	      onComplete: () => txt.destroy(),
184	    });
185	
186	    // ── 꽃받침 (연두색 타원) ──────────────────────────────────────────
187	    const base = scene.add.graphics().setDepth(196).setScale(0);
188	    base.fillStyle(0x66bb6a, 0.85);
189	    base.fillEllipse(0, 0, 62, 18);
190	    base.fillStyle(0x81c784, 0.6);
191	    base.fillEllipse(0, -3, 36, 10);
192	    base.setPosition(cx, cy + 2);
193	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
194	
195	    // ── 금빛 중앙 글로우 ──────────────────────────────────────────────
196	    const glow = scene.add.graphics().setDepth(197).setScale(0);
197	    glow.fillStyle(0xffd700, 0.20);
198	    glow.fillCircle(0, 0, 65);
199	    glow.fillStyle(0xffe082, 0.35);
200	    glow.fillCircle(0, 0, 38);
201	    glow.fillStyle(0xffffff, 0.55);
202	    glow.fillCircle(0, 0, 16);
203	    glow.setPosition(cx, cy - 28);
204	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
205	
206	    // ── 꽃잎 생성: glow_dot Image × 2 (본체 + 결) ────────────────────
207	    ensureGlowDot(scene);
208	    const petals: { body: Phaser.GameObjects.Image; vein: Phaser.GameObjects.Image; rotRad: number }[] = [];
209	
210	    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
