225	      // 중앙 결: 더 좁고 밝은 흰색
226	      const vein = scene.add.image(px, py, 'glow_dot')
227	        .setDepth(baseDepth + 0.01)
228	        .setBlendMode(Phaser.BlendModes.ADD)
229	        .setTint(0xffffff)
230	        .setRotation(rotRad)
231	        .setScale(0)
232	        .setAlpha(0.45);
233	
234	      const delay = idx * 40;
235	      scene.tweens.add({
236	        targets: body,
237	        scaleX: w / 64, scaleY: h / 64,
238	        delay, duration: 300, ease: 'Back.easeOut',
239	      });
240	      scene.tweens.add({
241	        targets: vein,
242	        scaleX: (w * 0.28) / 64, scaleY: (h * 0.72) / 64,
243	        delay: delay + 50, duration: 260, ease: 'Back.easeOut',
244	      });
245	
246	      petals.push({ body, vein, rotRad });
247	    });
248	
249	    // ── 수술 (stamen): glow_dot 금빛 구슬 2겹 ──────────────────────
250	    const stamenOuter = scene.add.image(cx, cy - 46, 'glow_dot')
251	      .setDepth(203).setBlendMode(Phaser.BlendModes.ADD)
252	      .setTint(0xffd700).setScale(0).setAlpha(0.7);
253	    const stamenInner = scene.add.image(cx, cy - 46, 'glow_dot')
254	      .setDepth(203.01).setBlendMode(Phaser.BlendModes.ADD)
255	      .setTint(0xffffff).setScale(0).setAlpha(0.9);
256	    const stamenDelay = LOTUS_DEFS.length * 40 - 20;
