258	    scene.tweens.add({ targets: stamenInner, scale: 0.16, delay: stamenDelay + 40, duration: 200, ease: 'Back.easeOut' });
259	    const stamen = [stamenOuter, stamenInner];
260	
261	    // ── 550ms 후: 수술 주변 금빛 파티클 ─────────────────────────────
262	    scene.time.delayedCall(550, () => {
263	      if (!scene.sys.isActive()) return;
264	      for (let j = 0; j < 10; j++) {
