277	          onComplete: () => g.destroy(),
278	        });
279	      }
280	    });
281	
282	    // ── 680ms 후: 꽃잎 비산 + 전체 똥 제거 ──────────────────────────
283	    scene.time.delayedCall(680, () => {
284	      if (!scene.sys.isActive()) return;
285	
286	      petals.forEach(({ body, vein, rotRad }) => {
287	        const tx = body.x + Math.sin(rotRad) * 155;
288	        const ty = body.y - Math.cos(rotRad) * 155;
289	        const rot = rotRad + Phaser.Math.FloatBetween(-0.7, 0.7);
290	        [body, vein].forEach(img => {
291	          scene.tweens.add({
292	            targets: img,
293	            x: tx, y: ty,
