309	
310	      this._clearAllPoops(api);
311	    });
312	
313	    this._updateCounter();
314	  }
315	
316	  // ── 화면 전체 일반 똥 제거 ─────────────────────────────────────────
317	  private _clearAllPoops(api: GameSceneAPI): void {
318	    const { poops, player, scene } = api;
319	    let cleared = 0;
320	
321	    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
322	      .filter(p => p.active)
323	      .forEach(p => {
324	        this._spawnPetalEffect(p.x, p.y, scene);
325	        (p as unknown as PoolablePoopBase).recycle();
326	        cleared++;
327	      });
328	
329	    if (cleared === 0) return;
330	
331	    const bonus = cleared * MUGI_PARAMS.lotusPoopBonus;
332	    api.addAbilityBonus(bonus);
333	
334	    const txt = scene.add.text(player.x, player.y - 35, `+${bonus}`, {
335	      fontSize: '19px',
336	      fontFamily: 'Arial Black, sans-serif',
337	      color: '#ff88cc',
338	      stroke: '#000000',
339	      strokeThickness: 4,
340	    }).setOrigin(0.5).setDepth(250);
341	    scene.tweens.add({
342	      targets: txt,
343	      y: txt.y - 52,
344	      alpha: 0,
345	      duration: 950,
346	      ease: 'Quad.easeOut',
347	      onComplete: () => txt.destroy(),
348	    });
349	  }
