351	  private _spawnPetalEffect(x: number, y: number, scene: Phaser.Scene): void {
352	    const colors = [0xffffff, 0xffd700, 0xfff8e1];
353	    for (let i = 0; i < 3; i++) {
354	      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
355	      const g = scene.add.graphics().setDepth(205);
356	      g.fillStyle(colors[i % 3]!, 0.9);
