358	      g.setPosition(x, y).setRotation(angle);
359	      scene.tweens.add({
360	        targets: g,
361	        x: x + Math.cos(angle) * Phaser.Math.Between(10, 22),
362	        y: y + Math.sin(angle) * Phaser.Math.Between(10, 22),
363	        alpha: 0, scale: 0,
364	        duration: Phaser.Math.Between(180, 300),
365	        ease: 'Quad.easeOut',
366	        onComplete: () => g.destroy(),
367	      });
368	    }
369	  }
370	
371	  // ── 정리 ────────────────────────────────────────────────────────────
372	  override onDestroy(_api: GameSceneAPI): void {
373	    this.yeoijus.forEach(orb => orb.gfx.destroy());
