import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MUGI_PARAMS } from '../config/abilityParams';
import { ensureGlowDot } from '../utils/glowDot';

// 옆면 연꽃 꽃잎 정의: [rotDeg, width, height, color, depth오프셋]
// 바닥 한 점에서 꽃잎 기울기에 따라 중심 자동 계산
const LOTUS_DEFS: [number, number, number, number, number][] = [
  // rotDeg  w    h      color      depthOff
  // ── 외층: 수평에 가깝게 드리워지는 꽃잎 ──
  [ -80,     20,  64,  0xfff3e0,    0 ],
  [  80,     20,  64,  0xfff3e0,    0 ],
  [ -66,     22,  68,  0xfff8e1,    0 ],
  [  66,     22,  68,  0xfff8e1,    0 ],
  // ── 중층 ──
  [ -52,     20,  63,  0xfffde7,    1 ],
  [  52,     20,  63,  0xfffde7,    1 ],
  [ -38,     18,  58,  0xfffde7,    2 ],
  [  38,     18,  58,  0xfffde7,    2 ],
  // ── 내층 ──
  [ -24,     17,  54,  0xffffff,    3 ],
  [  24,     17,  54,  0xffffff,    3 ],
  [ -11,     15,  50,  0xffffff,    3 ],
  [  11,     15,  50,  0xffffff,    3 ],
  // ── 중앙 ──
  [   0,     13,  44,  0xffffff,    4 ],
];

interface YeoijuOrb {
  gfx: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
}

export class MugiAbility extends BaseAbility {
  // ── 여의주 ──────────────────────────────────────────────────────────
  private lastYeoijuScore = 0;
  private yeoijuCount     = 0;
  private yeoijus: YeoijuOrb[] = [];

  // ── UI ──────────────────────────────────────────────────────────────
  private counterText: Phaser.GameObjects.Text | null = null;

  override onCreate(api: GameSceneAPI): void {
    this.lastYeoijuScore = 0;
    this.yeoijuCount     = 0;
    this.yeoijus         = [];
    this.counterText     = null;

    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.lotusThreshold}`, {
      fontSize: '11px',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 3,
    }).setDepth(500).setAlpha(0.88);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
      this.lastYeoijuScore = score;
      this._spawnYeoiju(api);
    }
  }

  // ── 여의주 생성 ─────────────────────────────────────────────────────
  private _spawnYeoiju(api: GameSceneAPI): void {
    const scene = api.scene;
    const x = Phaser.Math.Between(30, 370);

    const gfx = scene.add.graphics().setDepth(150);
    gfx.fillStyle(0xff2222, 0.12);
    gfx.fillCircle(0, 0, 20);
    gfx.fillStyle(0xff2222, 0.38);
    gfx.fillCircle(0, 0, 13);
    gfx.fillStyle(0xff3333, 1);
    gfx.fillCircle(0, 0, 8);
    gfx.fillStyle(0xff9999, 0.85);
    gfx.fillCircle(0, 0, 5);
    gfx.fillStyle(0xffffff, 0.75);
    gfx.fillCircle(-2.5, -3, 2.2);
    gfx.setPosition(x, -20);

    scene.tweens.add({
      targets: gfx,
      alpha: { from: 0.72, to: 1 },
      yoyo: true,
      repeat: -1,
      duration: 720,
      ease: 'Sine.easeInOut',
    });

    this.yeoijus.push({ gfx, x, y: -20 });
  }

  // ── 매 프레임 ───────────────────────────────────────────────────────
  override onUpdate(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta * 0.001;
    const { player } = api;
    const fallSpeed = api.baseSpeed + api.difficultyLevel * 40;
    const fallDelta = fallSpeed * delta;
    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
    const remaining: YeoijuOrb[] = [];

    for (const orb of this.yeoijus) {
      orb.y += fallDelta;
      orb.gfx.setPosition(orb.x, orb.y);

      const dx = player.x - orb.x;
      const dy = player.y - orb.y;
      if (dx * dx + dy * dy < r2) {
        this._collectYeoiju(orb, api);
        continue;
      }
      if (orb.y > 660) {
        orb.gfx.destroy();
        continue;
      }
      remaining.push(orb);
    }
    this.yeoijus = remaining;
  }

  // ── 여의주 수집 ─────────────────────────────────────────────────────
  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
    this._spawnCollectEffect(orb.x, orb.y, api.scene);
    orb.gfx.destroy();
    this.yeoijuCount++;
    this._updateCounter();

    if (this.yeoijuCount >= MUGI_PARAMS.lotusThreshold) {
      this.yeoijuCount = 0;
      this._activateLotus(api);
    }
  }

  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(160);
      g.fillStyle(0xff3333, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(200, 360),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  private _updateCounter(): void {
    if (!this.counterText) return;
    this.counterText
      .setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.lotusThreshold}`)
      .setColor('#ff88cc');
  }

  // ── 연화 소환 (옆면 연꽃) ───────────────────────────────────────────
  private _activateLotus(api: GameSceneAPI): void {
    const { scene, player } = api;
    const cx = player.x;
    const cy = player.y - 5; // 플레이어 중심보다 살짝 위

    scene.cameras.main.flash(280, 255, 240, 210, true);

    // 소환 텍스트
    const txt = scene.add.text(cx, cy - 92, '🌸 연화 청정!', {
      fontSize: '17px',
      fontFamily: 'Arial Black, sans-serif',
      color: '#fffde7',
      stroke: '#000000',
      strokeThickness: 5,
    }).setOrigin(0.5).setDepth(260);
    scene.tweens.add({
      targets: txt, y: txt.y - 60, alpha: 0,
      duration: 1500, ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });

    // ── 꽃받침 (연두색 타원) ──────────────────────────────────────────
    const base = scene.add.graphics().setDepth(196).setScale(0);
    base.fillStyle(0x66bb6a, 0.85);
    base.fillEllipse(0, 0, 62, 18);
    base.fillStyle(0x81c784, 0.6);
    base.fillEllipse(0, -3, 36, 10);
    base.setPosition(cx, cy + 2);
    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });

    // ── 금빛 중앙 글로우 ──────────────────────────────────────────────
    const glow = scene.add.graphics().setDepth(197).setScale(0);
    glow.fillStyle(0xffd700, 0.20);
    glow.fillCircle(0, 0, 65);
    glow.fillStyle(0xffe082, 0.35);
    glow.fillCircle(0, 0, 38);
    glow.fillStyle(0xffffff, 0.55);
    glow.fillCircle(0, 0, 16);
    glow.setPosition(cx, cy - 28);
    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });

    // ── 꽃잎 생성: glow_dot Image × 2 (본체 + 결) ────────────────────
    ensureGlowDot(scene);
    const petals: { body: Phaser.GameObjects.Image; vein: Phaser.GameObjects.Image; rotRad: number }[] = [];

    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
      const rotRad = rotDeg * Math.PI / 180;
      const px = cx + Math.sin(rotRad) * (h / 2);
      const py = (cy + 2) - Math.cos(rotRad) * (h / 2);
      const baseDepth = 197 + depthOff;

      // 본체: 꽃잎 색상 + ADD 블렌드
      const body = scene.add.image(px, py, 'glow_dot')
        .setDepth(baseDepth)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(color)
        .setRotation(rotRad)
        .setScale(0)
        .setAlpha(0.78);

      // 중앙 결: 더 좁고 밝은 흰색
      const vein = scene.add.image(px, py, 'glow_dot')
        .setDepth(baseDepth + 0.01)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(0xffffff)
        .setRotation(rotRad)
        .setScale(0)
        .setAlpha(0.45);

      const delay = idx * 40;
      scene.tweens.add({
        targets: body,
        scaleX: w / 64, scaleY: h / 64,
        delay, duration: 300, ease: 'Back.easeOut',
      });
      scene.tweens.add({
        targets: vein,
        scaleX: (w * 0.28) / 64, scaleY: (h * 0.72) / 64,
        delay: delay + 50, duration: 260, ease: 'Back.easeOut',
      });

      petals.push({ body, vein, rotRad });
    });

    // ── 수술 (stamen): glow_dot 금빛 구슬 2겹 ──────────────────────
    const stamenOuter = scene.add.image(cx, cy - 46, 'glow_dot')
      .setDepth(203).setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xffd700).setScale(0).setAlpha(0.7);
    const stamenInner = scene.add.image(cx, cy - 46, 'glow_dot')
      .setDepth(203.01).setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xffffff).setScale(0).setAlpha(0.9);
    const stamenDelay = LOTUS_DEFS.length * 40 - 20;
    scene.tweens.add({ targets: stamenOuter, scale: 0.38, delay: stamenDelay, duration: 240, ease: 'Back.easeOut' });
    scene.tweens.add({ targets: stamenInner, scale: 0.16, delay: stamenDelay + 40, duration: 200, ease: 'Back.easeOut' });
    const stamen = [stamenOuter, stamenInner];

    // ── 550ms 후: 수술 주변 금빛 파티클 ─────────────────────────────
    scene.time.delayedCall(550, () => {
      if (!scene.sys.isActive()) return;
      for (let j = 0; j < 10; j++) {
        const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
        const g = scene.add.graphics().setDepth(204);
        g.fillStyle(0xffd700, 1);
        g.fillCircle(0, 0, Phaser.Math.Between(3, 5));
        g.setPosition(cx, cy - 46);
        scene.tweens.add({
          targets: g,
          x: cx + Math.cos(angle) * Phaser.Math.Between(22, 50),
          y: (cy - 46) + Math.sin(angle) * Phaser.Math.Between(14, 36),
          alpha: 0, scale: 0,
          duration: Phaser.Math.Between(280, 420),
          ease: 'Quad.easeOut',
          onComplete: () => g.destroy(),
        });
      }
    });

    // ── 680ms 후: 꽃잎 비산 + 전체 똥 제거 ──────────────────────────
    scene.time.delayedCall(680, () => {
      if (!scene.sys.isActive()) return;

      petals.forEach(({ body, vein, rotRad }) => {
        const tx = body.x + Math.sin(rotRad) * 155;
        const ty = body.y - Math.cos(rotRad) * 155;
        const rot = rotRad + Phaser.Math.FloatBetween(-0.7, 0.7);
        [body, vein].forEach(img => {
          scene.tweens.add({
            targets: img,
            x: tx, y: ty,
            scaleX: 0, scaleY: 0,
            alpha: 0, rotation: rot,
            duration: 420, ease: 'Quad.easeOut',
            onComplete: () => img.destroy(),
          });
        });
      });

      [...stamen, glow, base].forEach(obj => {
        scene.tweens.add({
          targets: obj, alpha: 0, scale: 0,
          duration: 360, ease: 'Quad.easeOut',
          onComplete: () => obj.destroy(),
        });
      });

      this._clearAllPoops(api);
    });

    this._updateCounter();
  }

  // ── 화면 전체 일반 똥 제거 ─────────────────────────────────────────
  private _clearAllPoops(api: GameSceneAPI): void {
    const { poops, player, scene } = api;
    let cleared = 0;

    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active)
      .forEach(p => {
        this._spawnPetalEffect(p.x, p.y, scene);
        (p as unknown as PoolablePoopBase).recycle();
        cleared++;
      });

    if (cleared === 0) return;

    const bonus = cleared * MUGI_PARAMS.lotusPoopBonus;
    api.addAbilityBonus(bonus);

    const txt = scene.add.text(player.x, player.y - 35, `+${bonus}`, {
      fontSize: '19px',
      fontFamily: 'Arial Black, sans-serif',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 4,
    }).setOrigin(0.5).setDepth(250);
    scene.tweens.add({
      targets: txt,
      y: txt.y - 52,
      alpha: 0,
      duration: 950,
      ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });
  }

  private _spawnPetalEffect(x: number, y: number, scene: Phaser.Scene): void {
    const colors = [0xffffff, 0xffd700, 0xfff8e1];
    for (let i = 0; i < 3; i++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(205);
      g.fillStyle(colors[i % 3]!, 0.9);
      g.fillEllipse(0, 0, 5, 10);
      g.setPosition(x, y).setRotation(angle);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(10, 22),
        y: y + Math.sin(angle) * Phaser.Math.Between(10, 22),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(180, 300),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  // ── 정리 ────────────────────────────────────────────────────────────
  override onDestroy(_api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.destroy();
    this.counterText = null;
  }
}

