49	export class MugiAbility extends BaseAbility {
50	  // ── 여의주 ──────────────────────────────────────────────────────────
51	  private lastYeoijuScore = 0;
52	  private yeoijuCount     = 0;
53	  private yeoijus: YeoijuOrb[] = [];
54	
55	  // ── 연꽃 추적 상태 ──────────────────────────────────────────────────
56	  private lotusActive      = false;
57	  private lotusBurstTimer  = 0;
58	  private lotusStamenFired = false;
59	  private lotusPetals:  LotusPetal[]                       = [];
60	  private lotusBaseGfx: Phaser.GameObjects.Graphics | null = null;
61	  private lotusGlowGfx: Phaser.GameObjects.Graphics | null = null;
62	  private lotusStamens: Phaser.GameObjects.Image[]         = [];
63	
