65	  private counterText: Phaser.GameObjects.Text | null = null;
66	
67	  override onCreate(api: GameSceneAPI): void {
68	    this.lastYeoijuScore = 0;
69	    this.yeoijuCount     = 0;
70	    this.yeoijus         = [];
71	    this.lotusActive     = false;
72	    this.lotusBurstTimer = 0;
73	    this.lotusStamenFired= false;
74	    this.lotusPetals     = [];
75	    this.lotusBaseGfx    = null;
