78	    this.counterText     = null;
79	
80	    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.lotusThreshold}`, {
81	      fontSize: '11px',
82	      color: '#ff88cc',
83	      stroke: '#000000',
84	      strokeThickness: 3,
85	    }).setDepth(500).setAlpha(0.88);
86	  }
87	
88	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
89	    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
90	      this.lastYeoijuScore = score;
91	      this._spawnYeoiju(api);
92	    }
93	  }
94	
95	  // ── 여의주 생성 ─────────────────────────────────────────────────────
96	  private _spawnYeoiju(api: GameSceneAPI): void {
97	    const scene = api.scene;
98	    const x = Phaser.Math.Between(30, 370);
99	
100	    const gfx = scene.add.graphics().setDepth(150);
101	    gfx.fillStyle(0xff2222, 0.12); gfx.fillCircle(0, 0, 20);
102	    gfx.fillStyle(0xff2222, 0.38); gfx.fillCircle(0, 0, 13);
103	    gfx.fillStyle(0xff3333, 1);    gfx.fillCircle(0, 0, 8);
104	    gfx.fillStyle(0xff9999, 0.85); gfx.fillCircle(0, 0, 5);
105	    gfx.fillStyle(0xffffff, 0.75); gfx.fillCircle(-2.5, -3, 2.2);
106	    gfx.setPosition(x, -20);
107	
108	    scene.tweens.add({
109	      targets: gfx, alpha: { from: 0.72, to: 1 },
110	      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
111	    });
112	
113	    this.yeoijus.push({ gfx, x, y: -20 });
114	  }
115	
116	  // ── 매 프레임 ───────────────────────────────────────────────────────
117	  override onUpdate(api: GameSceneAPI): void {
118	    this._updateYeoijus(api);
119	    if (this.lotusActive) this._updateLotus(api);
120	  }
121	
122	  private _updateYeoijus(api: GameSceneAPI): void {
123	    const delta = api.scene.game.loop.delta * 0.001;
124	    const { player } = api;
125	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
126	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
127	    const remaining: YeoijuOrb[] = [];
128	
129	    for (const orb of this.yeoijus) {
130	      orb.y += fallDelta;
131	      orb.gfx.setPosition(orb.x, orb.y);
132	
133	      const dx = player.x - orb.x;
134	      const dy = player.y - orb.y;
135	      if (dx * dx + dy * dy < r2) {
136	        this._collectYeoiju(orb, api);
137	        continue;
138	      }
139	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
140	      remaining.push(orb);
141	    }
142	    this.yeoijus = remaining;
143	  }
144	
145	  private _updateLotus(api: GameSceneAPI): void {
146	    const dt = api.scene.game.loop.delta;
147	    this.lotusBurstTimer -= dt;
148	
149	    // 위치 추적
150	    this._syncLotusPosition(api.player);
151	
152	    // 수술 파티클 (bloom 완료 직후 1회)
153	    if (!this.lotusStamenFired && this.lotusBurstTimer <= LOTUS_STAMEN_FIRE_AT) {
154	      this.lotusStamenFired = true;
155	      this._fireStamenParticles(api);
156	    }
157	
158	    if (this.lotusBurstTimer <= 0) {
159	      this._burstLotus(api);
160	    }
161	  }
162	
163	  // 플레이어 위치 기준으로 모든 연꽃 오브젝트 위치 동기화
164	  private _syncLotusPosition(player: Phaser.Physics.Arcade.Sprite): void {
165	    const bx = player.x;
166	    const by = player.y + LOTUS_BASE_OFFSET_Y;
167	
168	    this.lotusBaseGfx?.setPosition(bx, by);
169	    this.lotusGlowGfx?.setPosition(bx, by - LOTUS_GLOW_OFFSET_Y);
170	    this.lotusStamens.forEach(s => s.setPosition(bx, by - LOTUS_STAMEN_OFFSET_Y));
171	
172	    this.lotusPetals.forEach(({ body, vein, tip, rotRad, h }) => {
173	      const px = bx + Math.sin(rotRad) * (h / 2);
174	      const py = by - Math.cos(rotRad) * (h / 2);
175	      body.setPosition(px, py);
176	      vein.setPosition(px, py);
177	      tip.setPosition(bx + Math.sin(rotRad) * h * 0.875, by - Math.cos(rotRad) * h * 0.875);
178	    });
179	  }
180	
181	  // ── 여의주 수집 ─────────────────────────────────────────────────────
182	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
183	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
184	    orb.gfx.destroy();
185	    this.yeoijuCount++;
186	    this._updateCounter();
187	
188	    if (this.yeoijuCount >= MUGI_PARAMS.lotusThreshold && !this.lotusActive) {
189	      this.yeoijuCount = 0;
190	      this._activateLotus(api);
191	    }
192	  }
193	
194	  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
195	    for (let i = 0; i < 6; i++) {
196	      const angle = (i / 6) * Math.PI * 2;
197	      const g = scene.add.graphics().setDepth(160);
198	      g.fillStyle(0xff3333, 1);
199	      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
200	      g.setPosition(x, y);
201	      scene.tweens.add({
202	        targets: g,
203	        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
204	        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
205	        alpha: 0, scale: 0,
206	        duration: Phaser.Math.Between(200, 360),
207	        ease: 'Quad.easeOut',
208	        onComplete: () => g.destroy(),
209	      });
210	    }
211	  }
212	
213	  private _updateCounter(): void {
214	    if (!this.counterText) return;
215	    this.counterText
216	      .setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.lotusThreshold}`)
217	      .setColor('#ff88cc');
218	  }
219	
220	  // ── 연화 소환 ───────────────────────────────────────────────────────
221	  private _activateLotus(api: GameSceneAPI): void {
222	    const { scene, player } = api;
223	    ensureGlowDot(scene);
224	
225	    this.lotusActive      = true;
226	    this.lotusBurstTimer  = LOTUS_FOLLOW_MS;
227	    this.lotusStamenFired = false;
228	
229	    scene.cameras.main.flash(280, 255, 240, 210, true);
230	
231	    // 소환 텍스트 (1회성 — 따라다니지 않음)
232	    const txt = scene.add.text(player.x, player.y - 90, '🌸 연화 청정!', {
233	      fontSize: '17px', fontFamily: 'Arial Black, sans-serif',
234	      color: '#fffde7', stroke: '#000000', strokeThickness: 5,
235	    }).setOrigin(0.5).setDepth(260);
236	    scene.tweens.add({
237	      targets: txt, y: txt.y - 60, alpha: 0,
238	      duration: 1400, ease: 'Quad.easeOut',
239	      onComplete: () => txt.destroy(),
240	    });
241	
242	    const bx = player.x;
243	    const by = player.y + LOTUS_BASE_OFFSET_Y;
244	
245	    // ── 꽃받침 ────────────────────────────────────────────────────────
246	    const base = scene.add.graphics().setDepth(196).setScale(0);
247	    base.fillStyle(0x66bb6a, 0.85); base.fillEllipse(0, 0, 62, 18);
248	    base.fillStyle(0x81c784, 0.6);  base.fillEllipse(0, -3, 36, 10);
249	    base.setPosition(bx, by);
250	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
251	    this.lotusBaseGfx = base;
252	
253	    // ── 중앙 글로우 ───────────────────────────────────────────────────
254	    const glow = scene.add.graphics().setDepth(197).setScale(0);
255	    glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 65);
256	    glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 38);
257	    glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0, 16);
258	    glow.setPosition(bx, by - LOTUS_GLOW_OFFSET_Y);
259	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
260	    this.lotusGlowGfx = glow;
261	
262	    // ── 꽃잎 (glow_dot × 2층) ─────────────────────────────────────────
263	    this.lotusPetals = [];
264	    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
265	      const rotRad   = rotDeg * Math.PI / 180;
266	      const px       = bx + Math.sin(rotRad) * (h / 2);
267	      const py       = by - Math.cos(rotRad) * (h / 2);
268	      const baseDepth = 197 + depthOff;
269	
270	      const body = scene.add.image(px, py, 'glow_dot')
271	        .setDepth(baseDepth).setBlendMode(Phaser.BlendModes.ADD)
272	        .setTint(color).setRotation(rotRad).setScale(0).setAlpha(0.78);
273	
274	      const vein = scene.add.image(px, py, 'glow_dot')
275	        .setDepth(baseDepth + 0.01).setBlendMode(Phaser.BlendModes.ADD)
