import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MUGI_PARAMS } from '../config/abilityParams';
import { ensureGlowDot } from '../utils/glowDot';

interface YeoijuOrb {
  gfx: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
}

export class MugiAbility extends BaseAbility {
  private lastYeoijuScore = 0;
  private yeoijuCount     = 0;
  private yeoijus: YeoijuOrb[] = [];
  private counterText: Phaser.GameObjects.Text | null = null;

  override onCreate(api: GameSceneAPI): void {
    this.lastYeoijuScore = 0;
    this.yeoijuCount     = 0;
    this.yeoijus         = [];
    this.counterText     = null;

    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.lotusThreshold}`, {
      fontSize: '11px',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 3,
    }).setDepth(500).setAlpha(0.88);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MUGI_PARAMS.yeoijuInterval === 0 && score > this.lastYeoijuScore) {
      this.lastYeoijuScore = score;
      this._spawnYeoiju(api);
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    this._updateYeoijus(api);
  }

  // ── 여의주 ──────────────────────────────────────────────────────────

  private _spawnYeoiju(api: GameSceneAPI): void {
    const scene = api.scene;
    const x = Phaser.Math.Between(30, 370);

    const gfx = scene.add.graphics().setDepth(150);
    gfx.fillStyle(0xff2222, 0.12); gfx.fillCircle(0, 0, 20);
    gfx.fillStyle(0xff2222, 0.38); gfx.fillCircle(0, 0, 13);
    gfx.fillStyle(0xff3333, 1);    gfx.fillCircle(0, 0, 8);
    gfx.fillStyle(0xff9999, 0.85); gfx.fillCircle(0, 0, 5);
    gfx.fillStyle(0xffffff, 0.75); gfx.fillCircle(-2.5, -3, 2.2);
    gfx.setPosition(x, -20);

    scene.tweens.add({
      targets: gfx, alpha: { from: 0.72, to: 1 },
      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
    });

    this.yeoijus.push({ gfx, x, y: -20 });
  }

  private _updateYeoijus(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta * 0.001;
    const { player } = api;
    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
    const remaining: YeoijuOrb[] = [];

    for (const orb of this.yeoijus) {
      orb.y += fallDelta;
      orb.gfx.setPosition(orb.x, orb.y);

      const dx = player.x - orb.x;
      const dy = player.y - orb.y;
      if (dx * dx + dy * dy < r2) {
        this._collectYeoiju(orb, api);
        continue;
      }
      if (orb.y > 660) { orb.gfx.destroy(); continue; }
      remaining.push(orb);
    }
    this.yeoijus = remaining;
  }

  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
    this._spawnCollectEffect(orb.x, orb.y, api.scene);
    orb.gfx.destroy();
    this.yeoijuCount++;
    this._updateCounter();

    if (this.yeoijuCount >= MUGI_PARAMS.lotusThreshold) {
      this.yeoijuCount = 0;
      this._activateLotus(api);
    }
  }

  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(160);
      g.fillStyle(0xff3333, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(200, 360),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  private _updateCounter(): void {
    if (!this.counterText) return;
    this.counterText.setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.lotusThreshold}`);
  }

  // ── 연화 소환 ───────────────────────────────────────────────────────

  private _activateLotus(api: GameSceneAPI): void {
    const { scene, player } = api;
    ensureGlowDot(scene);

    scene.cameras.main.flash(200, 255, 220, 240, true);

    const txt = scene.add.text(player.x, player.y - 80, '🌸 연화 청정!', {
      fontSize: '17px', fontFamily: 'Arial Black, sans-serif',
      color: '#fffde7', stroke: '#000000', strokeThickness: 5,
    }).setOrigin(0.5).setDepth(260);
    scene.tweens.add({
      targets: txt, y: txt.y - 60, alpha: 0,
      duration: 1400, ease: 'Quad.easeOut',
      onComplete: () => txt.destroy(),
    });

    for (let i = 0; i < MUGI_PARAMS.lotusCount; i++) {
      const lx = Phaser.Math.Between(30, 370);
      const minY = Math.max(20, player.y - 220);
      const maxY = Math.max(minY + 10, player.y - 50);
      const ly   = Phaser.Math.Between(minY, maxY);
      this._spawnSingleLotus(lx, ly, i * 70, api);
    }

    this._updateCounter();
  }

  private _spawnSingleLotus(lx: number, ly: number, delay: number, api: GameSceneAPI): void {
    const { scene } = api;
    const S = MUGI_PARAMS.lotusSize; // 52px

    const outer = scene.add.image(lx, ly, 'glow_dot')
      .setDepth(200).setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xffaacc).setScale(0).setAlpha(0.55);
    const inner = scene.add.image(lx, ly, 'glow_dot')
      .setDepth(201).setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xffeeff).setScale(0).setAlpha(0.85);
    const center = scene.add.image(lx, ly, 'glow_dot')
      .setDepth(202).setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xffd700).setScale(0).setAlpha(1);

    scene.tweens.add({ targets: outer,  scaleX: S / 64,            scaleY: S / 64,            delay,        duration: 220, ease: 'Back.easeOut' });
    scene.tweens.add({ targets: inner,  scaleX: (S * 0.65) / 64,   scaleY: (S * 0.65) / 64,   delay: delay + 40,  duration: 200, ease: 'Back.easeOut' });
    scene.tweens.add({ targets: center, scaleX: (S * 0.28) / 64,   scaleY: (S * 0.28) / 64,   delay: delay + 80,  duration: 180, ease: 'Back.easeOut',
      onComplete: () => {
        scene.time.delayedCall(300, () => {
          if (!scene.sys.isActive()) return;
          [outer, inner, center].forEach(img => {
            if (!img.active) return;
            scene.tweens.add({
              targets: img,
              scaleX: img.scaleX * 2.4, scaleY: img.scaleY * 2.4,
              alpha: 0, duration: 260, ease: 'Quad.easeOut',
              onComplete: () => img.destroy(),
            });
          });
          this._zapPoopsNear(lx, ly, MUGI_PARAMS.lotusRadius, api);
        });
      },
    });
  }

  // ── 폭발 범위 내 똥 제거 ────────────────────────────────────────────

  private _zapPoopsNear(cx: number, cy: number, radius: number, api: GameSceneAPI): void {
    const { poops, scene } = api;
    const r2 = radius * radius;
    let cleared = 0;

    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && (p.x - cx) ** 2 + (p.y - cy) ** 2 <= r2)
      .forEach(p => {
        this._spawnPetalEffect(p.x, p.y, scene);
        (p as unknown as PoolablePoopBase).recycle();
        cleared++;
      });

    if (cleared === 0) return;

    const bonus = cleared * MUGI_PARAMS.lotusPoopBonus;
    api.addAbilityBonus(bonus);

    const bonusTxt = scene.add.text(cx, cy - 20, `+${bonus}`, {
      fontSize: '16px', fontFamily: 'Arial Black, sans-serif',
      color: '#ff88cc', stroke: '#000000', strokeThickness: 4,
    }).setOrigin(0.5).setDepth(250);
    scene.tweens.add({
      targets: bonusTxt, y: bonusTxt.y - 40, alpha: 0,
      duration: 850, ease: 'Quad.easeOut',
      onComplete: () => bonusTxt.destroy(),
    });
  }

  private _spawnPetalEffect(x: number, y: number, scene: Phaser.Scene): void {
    const colors = [0xffffff, 0xffd700, 0xfff8e1];
    for (let i = 0; i < 3; i++) {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const g = scene.add.graphics().setDepth(205);
      g.fillStyle(colors[i % 3]!, 0.9);
      g.fillEllipse(0, 0, 5, 10);
      g.setPosition(x, y).setRotation(angle);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(10, 22),
        y: y + Math.sin(angle) * Phaser.Math.Between(10, 22),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(180, 300),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  // ── 정리 ────────────────────────────────────────────────────────────

  override onDestroy(_api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.destroy();
    this.counterText = null;
  }
}

/**
 * 캐릭터 능력 수치 설정 (단일 진실 공급원)
 *
 * PARAMS  — 능력 클래스에서 사용하는 숫자/비율 값
 * DESC    — PARAMS로 자동 생성되는 설명 문자열 (character.ts에서 import)
 *
 * 수치를 바꾸면 게임 로직과 캐릭터 정보 패널이 동시에 갱신됩니다.
 */

