// ── 황금 변신 (1회성) ────────────────────────────────────────────────

private _transformGold(api: GameSceneAPI): void {
  this.isGoldForm = true;

  this.yeoijus.forEach(orb => orb.gfx.destroy());
  this.yeoijus = [];
  this.counterText?.setVisible(false);

  this._strikeThunder(api);
}

private _strikeThunder(api: GameSceneAPI): void {
  const { scene, player } = api;
  const tx = player.x;
  const ty = player.y;

  // 강한 노란 플래시
  scene.cameras.main.flash(600, 255, 230, 0, true);

  // 번개 Graphics (단일 객체 재사용)
  const g = scene.add.graphics().setDepth(310);

  const drawBolt = () => {
    g.clear();

    // 지그재그 포인트 생성 (화면 상단 → 플레이어)
    const pts: { x: number; y: number }[] = [{ x: tx + Phaser.Math.Between(-15, 15), y: -10 }];
    const segs = 12;
    for (let i = 1; i < segs; i++) {
      const t = i / segs;
      pts.push({ x: tx + Phaser.Math.Between(-45, 45), y: (ty + 20) * t });
    }
    pts.push({ x: tx, y: ty + 10 });

    // 외곽 글로우 (넓고 반투명)
    g.lineStyle(28, 0xffcc00, 0.25);
    this._drawPolyline(g, pts);

    // 중간 레이어
    g.lineStyle(12, 0xffee00, 0.75);
    this._drawPolyline(g, pts);

    // 코어 (흰색)
    g.lineStyle(4, 0xffffff, 1);
    this._drawPolyline(g, pts);

    // 가지 2개
    for (let b = 0; b < 2; b++) {
      const bi = 3 + b * 3;
      if (bi >= pts.length) break;
      const bp = pts[bi]!;
      const bx2 = bp.x + Phaser.Math.Between(-80, 80);
      const by2 = bp.y + Phaser.Math.Between(40, 100);
      g.lineStyle(5, 0xffee00, 0.6);
      g.beginPath(); g.moveTo(bp.x, bp.y); g.lineTo(bx2, by2); g.strokePath();
      g.lineStyle(2, 0xffffff, 0.8);
      g.beginPath(); g.moveTo(bp.x, bp.y); g.lineTo(bx2, by2); g.strokePath();
    }
  };

  // 3회 재그림으로 지글 효과
  drawBolt();
  [80, 160].forEach(delay => {
    scene.time.delayedCall(delay, () => {
      if (!scene.sys.isActive() || !g.active) return;
      drawBolt();
    });
  });

  // 번개 페이드아웃
  scene.tweens.add({
    targets: g, alpha: 0, delay: 220, duration: 350, ease: 'Quad.easeOut',
    onComplete: () => g.destroy(),
  });

  // 착탄 임팩트 원
  const impact = scene.add.graphics().setDepth(308);
  impact.fillStyle(0xffee00, 0.7);
  impact.fillCircle(tx, ty, 55);
  scene.tweens.add({
    targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
    duration: 500, ease: 'Quad.easeOut',
    onComplete: () => impact.destroy(),
  });

  // 착탄 링
  const ring = scene.add.graphics().setDepth(309);
  ring.lineStyle(4, 0xffffff, 1);
  ring.strokeCircle(tx, ty, 40);
  scene.tweens.add({
    targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
    duration: 450, ease: 'Quad.easeOut',
    onComplete: () => ring.destroy(),
  });

  // 변신 텍스트
  const txt = scene.add.text(tx, ty - 90, '⚡ 황금 변신!', {
    fontSize: '20px', fontFamily: 'Arial Black, sans-serif',
    color: '#ffd700', stroke: '#000000', strokeThickness: 6,
  }).setOrigin(0.5).setDepth(320);
  scene.tweens.add({
    targets: txt, y: txt.y - 65, alpha: 0,
    duration: 1500, ease: 'Quad.easeOut',
    onComplete: () => txt.destroy(),
  });

  // 골드 스프라이트 전환 + 전체 똥 삭제 (벼락 착탄 타이밍에)
  scene.time.delayedCall(180, () => {
    if (!scene.sys.isActive()) return;
    api.player.setTexturePrefix('gold_mugi_');
    this._clearAllPoops(api);
  });
}

private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
  g.beginPath();
  g.moveTo(pts[0]!.x, pts[0]!.y);
  for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
  g.strokePath();
}

private _clearAllPoops(api: GameSceneAPI): void {
  const { poops, player, scene } = api;
  let cleared = 0;

  (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
    .filter(p => p.active)
    .forEach(p => {
      // 제거 파티클
      for (let i = 0; i < 3; i++) {
        const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
        const spark = scene.add.graphics().setDepth(205);
        spark.fillStyle(0xffee00, 1);
        spark.fillCircle(0, 0, Phaser.Math.Between(2, 4));
        spark.setPosition(p.x, p.y);
        scene.tweens.add({
          targets: spark,
          x: p.x + Math.cos(angle) * Phaser.Math.Between(10, 25),
          y: p.y + Math.sin(angle) * Phaser.Math.Between(10, 25),
          alpha: 0, scale: 0,
          duration: Phaser.Math.Between(180, 300),
          ease: 'Quad.easeOut',
          onComplete: () => spark.destroy(),
        });
      }
      (p as unknown as PoolablePoopBase).recycle();
      cleared++;
    });

  if (cleared === 0) return;

  const bonusTxt = scene.add.text(player.x, player.y - 40, `⚡ ×${cleared} 소멸!`, {
    fontSize: '17px', fontFamily: 'Arial Black, sans-serif',
    color: '#ffd700', stroke: '#000000', strokeThickness: 4,
  }).setOrigin(0.5).setDepth(320);
  scene.tweens.add({
    targets: bonusTxt, y: bonusTxt.y - 55, alpha: 0,
    duration: 1200, ease: 'Quad.easeOut',
    onComplete: () => bonusTxt.destroy(),
  });
}

