    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
    g.strokePath();
  }

  private _clearAllPoops(api: GameSceneAPI): void {
    const { poops, player, scene } = api;
    let cleared = 0;

    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active)
      .forEach(p => {
        // 제거 파티클
        for (let i = 0; i < 3; i++) {
          const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
          const spark = scene.add.graphics().setDepth(205);
          spark.fillStyle(0xffee00, 1);
          spark.fillCircle(0, 0, Phaser.Math.Between(2, 4));
          spark.setPosition(p.x, p.y);
          scene.tweens.add({
            targets: spark,
            x: p.x + Math.cos(angle) * Phaser.Math.Between(10, 25),
            y: p.y + Math.sin(angle) * Phaser.Math.Between(10, 25),
            alpha: 0, scale: 0,
            duration: Phaser.Math.Between(180, 300),
            ease: 'Quad.easeOut',
            onComplete: () => spark.destroy(),
          });
        }
