      fontSize: '17px', fontFamily: 'Arial Black, sans-serif',
      color: '#ffd700', stroke: '#000000', strokeThickness: 4,
    }).setOrigin(0.5).setDepth(320);
    scene.tweens.add({
      targets: bonusTxt, y: bonusTxt.y - 55, alpha: 0,
      duration: 1200, ease: 'Quad.easeOut',
      onComplete: () => bonusTxt.destroy(),
    });
  }

