      g.clear();

      // 지그재그 포인트 생성 (화면 상단 → 플레이어)
      const pts: { x: number; y: number }[] = [{ x: tx + Phaser.Math.Between(-15, 15), y: -10 }];
      const segs = 12;
      for (let i = 1; i < segs; i++) {
        const t = i / segs;
        pts.push({ x: tx + Phaser.Math.Between(-45, 45), y: (ty + 20) * t });
      }
      pts.push({ x: tx, y: ty + 10 });

      // 외곽 글로우 (넓고 반투명)
      g.lineStyle(28, 0xffcc00, 0.25);
      this._drawPolyline(g, pts);

      // 중간 레이어
      g.lineStyle(12, 0xffee00, 0.75);
      this._drawPolyline(g, pts);

      // 코어 (흰색)
      g.lineStyle(4, 0xffffff, 1);
      this._drawPolyline(g, pts);

      // 가지 2개
      for (let b = 0; b < 2; b++) {
        const bi = 3 + b * 3;
        if (bi >= pts.length) break;
        const bp = pts[bi]!;
        const bx2 = bp.x + Phaser.Math.Between(-80, 80);
        const by2 = bp.y + Phaser.Math.Between(40, 100);
        g.lineStyle(5, 0xffee00, 0.6);
        g.beginPath(); g.moveTo(bp.x, bp.y); g.lineTo(bx2, by2); g.strokePath();
        g.lineStyle(2, 0xffffff, 0.8);
        g.beginPath(); g.moveTo(bp.x, bp.y); g.lineTo(bx2, by2); g.strokePath();
      }
    };

    // 3회 재그림으로 지글 효과
    drawBolt();
    [80, 160].forEach(delay => {
      scene.time.delayedCall(delay, () => {
        if (!scene.sys.isActive() || !g.active) return;
        drawBolt();
      });
    });

    // 번개 페이드아웃
    scene.tweens.add({
      targets: g, alpha: 0, delay: 220, duration: 350, ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    });

    // 착탄 임팩트 원
    const impact = scene.add.graphics().setDepth(308);
    impact.fillStyle(0xffee00, 0.7);
    impact.fillCircle(tx, ty, 55);
    scene.tweens.add({
      targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
      duration: 500, ease: 'Quad.easeOut',
      onComplete: () => impact.destroy(),
    });

    // 착탄 링
    const ring = scene.add.graphics().setDepth(309);
    ring.lineStyle(4, 0xffffff, 1);
    ring.strokeCircle(tx, ty, 40);
    scene.tweens.add({
      targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
      duration: 450, ease: 'Quad.easeOut',
      onComplete: () => ring.destroy(),
    });

    // 골드 스프라이트 전환 + 전체 똥 삭제 (벼락 착탄 타이밍에)
    scene.time.delayedCall(180, () => {
      if (!scene.sys.isActive()) return;
      api.player.setTexturePrefix('gold_mugi_');
      this._clearAllPoops(api);
    });
  }

  private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
    g.beginPath();
    g.moveTo(pts[0]!.x, pts[0]!.y);
    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
    g.strokePath();
  }

  private _clearAllPoops(api: GameSceneAPI): void {
    const { poops, player, scene } = api;

    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active);

    if (targets.length === 0) return;

    const cleared = targets.length;

    // 즉시 정지 + 파지직 이펙트
    targets.forEach(p => {
      (p.body as Phaser.Physics.Arcade.Body).setVelocityY(0);
      this._spawnZapEffect(p.x, p.y, scene);
    });

    // 450ms 후 실제 제거 + 점수
    scene.time.delayedCall(450, () => {
      if (!scene.sys.isActive()) return;
      targets.forEach(p => {
        if (p.active) (p as unknown as PoolablePoopBase).recycle();
      });

      const bonus = cleared * 10;
      api.addAbilityBonus(bonus);

      const bonusTxt = scene.add.text(player.x, player.y - 40, `⚡ +${bonus}점`, {
        fontSize: '18px', fontFamily: 'Arial Black, sans-serif',
        color: '#ffd700', stroke: '#000000', strokeThickness: 5,
      }).setOrigin(0.5).setDepth(320);
      scene.tweens.add({
        targets: bonusTxt, y: bonusTxt.y - 60, alpha: 0,
        duration: 1200, ease: 'Quad.easeOut',
        onComplete: () => bonusTxt.destroy(),
      });
    });
  }

  private _spawnZapEffect(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics().setDepth(206);

    const draw = () => {
      g.clear();
      const sparks = Phaser.Math.Between(3, 5);
      for (let i = 0; i < sparks; i++) {
        const color = Math.random() < 0.55 ? 0xffee00 : 0xffffff;
        g.lineStyle(Phaser.Math.FloatBetween(1.5, 2.5), color, 1);
        g.beginPath();
        let px = x + Phaser.Math.Between(-7, 7);
        let py = y + Phaser.Math.Between(-7, 7);
        g.moveTo(px, py);
        for (let j = 0; j < 3; j++) {
          px += Phaser.Math.Between(-10, 10);
          py += Phaser.Math.Between(-10, 10);
          g.lineTo(px, py);
        }
        g.strokePath();
      }
    };

    draw();

    // 80ms마다 재그림
    const timer = scene.time.addEvent({ delay: 80, repeat: 5, callback: draw });

    // 550ms 후 정리 (제거 시점인 450ms 이후까지 잠깐 유지)
    scene.time.delayedCall(550, () => {
      timer.remove();
      if (g.active) g.destroy();
    });
  }

  // ── 정리 ────────────────────────────────────────────────────────────

  override onDestroy(api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.destroy();
    this.counterText = null;
    if (this.isGoldForm) {
      api.player.setTexturePrefix(this.normalPrefix);
      this.isGoldForm = false;
    }
  }
}

