// ── 변신 전 — 검붉은 번개 (시각 효과만) ────────────────────────────

private _strikeRedLightning(api: GameSceneAPI): void {
  const { scene, player } = api;
  const tx = player.x;
  const ty = player.y;

  scene.cameras.main.flash(250, 120, 0, 0, true);

  const g = scene.add.graphics().setDepth(310);

  const makeRedPts = (startX: number) => {
    const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
    for (let i = 1; i < 14; i++) {
      const t = i / 14;
      const spread = 55 * (1 - t * 0.6);
      pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
    }
    pts.push({ x: tx, y: ty + 8 });
    return pts;
  };

  const drawRed = () => {
    g.clear();
    const pts = makeRedPts(tx + Phaser.Math.Between(-20, 20));

    g.lineStyle(36, 0x550000, 0.12); this._drawPolyline(g, pts);
    g.lineStyle(16, 0x990000, 0.40); this._drawPolyline(g, pts);
    g.lineStyle(7,  0xcc2200, 0.85); this._drawPolyline(g, pts);
    g.lineStyle(2.5, 0xff6644, 1.00); this._drawPolyline(g, pts);

    // 가지 2개
    [3, 8].forEach(bi => {
      if (bi >= pts.length - 1) return;
      const bp = pts[bi]!;
      const dir = Math.random() < 0.5 ? 1 : -1;
      const len = Phaser.Math.Between(40, 80);
      const bPts = [
        { x: bp.x, y: bp.y },
        { x: bp.x + dir * len * 0.4 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.4 },
        { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
      ];
      g.lineStyle(6,  0xaa1100, 0.45); this._drawPolyline(g, bPts);
      g.lineStyle(2,  0xff4422, 0.80); this._drawPolyline(g, bPts);
    });
  };

  drawRed();
  [55, 110, 165].forEach(delay => {
    scene.time.delayedCall(delay, () => {
      if (!scene.sys.isActive() || !g.active) return;
      drawRed();
    });
  });

