content.content:
  1	import Phaser from 'phaser';
  2	import { BaseAbility } from './BaseAbility';
  3	import type { GameSceneAPI } from './types';
  4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
  5	import { MUGI_PARAMS } from '../config/abilityParams';
  6	
  7	interface YeoijuOrb {
  8	  gfx: Phaser.GameObjects.Graphics;
  9	  x: number;
 10	  y: number;
 11	}
 12	
 13	export class MugiAbility extends BaseAbility {
 14	  private lastYeoijuScore = 0;
 15	  private yeoijuCount     = 0;
 16	  private yeoijus: YeoijuOrb[] = [];
 17	  private counterText: Phaser.GameObjects.Text | null = null;
 18	  private normalPrefix    = 'mugi_';
 19	  private isGoldForm      = false;
 20	
 21	  override onCreate(api: GameSceneAPI): void {
 22	    this.lastYeoijuScore = 0;
 23	    this.yeoijuCount     = 0;
 24	    this.yeoijus         = [];
 25	    this.counterText     = null;
 26	    this.normalPrefix    = api.player.getTexturePrefix();
 27	    this.isGoldForm      = false;
 28	
 29	    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.goldThreshold}`, {
 30	      fontSize: '11px',
 31	      color: '#ff88cc',
 32	      stroke: '#000000',
 33	      strokeThickness: 3,
 34	    }).setDepth(500).setAlpha(0.88);
 35	  }
 36	
 37	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
 38	    const interval = this.isGoldForm ? MUGI_PARAMS.yeoijuGoldInterval : MUGI_PARAMS.yeoijuInterval;
 39	    if (score % interval === 0 && score > this.lastYeoijuScore) {
 40	      this.lastYeoijuScore = score;
 41	      this._spawnYeoiju(api);
 42	    }
 43	  }
 44	
 45	  override onUpdate(api: GameSceneAPI): void {
 46	    this._updateYeoijus(api);
 47	  }
 48	
 49	  // ── 여의주 ──────────────────────────────────────────────────────────
 50	
 51	  private _spawnYeoiju(api: GameSceneAPI): void {
 52	    const scene = api.scene;
 53	    const x = Phaser.Math.Between(30, 370);
 54	
 55	    const gfx = scene.add.graphics().setDepth(150);
 56	    gfx.fillStyle(0xff2222, 0.12); gfx.fillCircle(0, 0, 20);
 57	    gfx.fillStyle(0xff2222, 0.38); gfx.fillCircle(0, 0, 13);
 58	    gfx.fillStyle(0xff3333, 1);    gfx.fillCircle(0, 0, 8);
 59	    gfx.fillStyle(0xff9999, 0.85); gfx.fillCircle(0, 0, 5);
 60	    gfx.fillStyle(0xffffff, 0.75); gfx.fillCircle(-2.5, -3, 2.2);
 61	    gfx.setPosition(x, -20);
 62	
 63	    scene.tweens.add({
 64	      targets: gfx, alpha: { from: 0.72, to: 1 },
 65	      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
 66	    });
 67	
 68	    this.yeoijus.push({ gfx, x, y: -20 });
 69	  }
 70	
 71	  private _updateYeoijus(api: GameSceneAPI): void {
 72	    const delta = api.scene.game.loop.delta * 0.001;
 73	    const { player } = api;
 74	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
 75	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
 76	    const remaining: YeoijuOrb[] = [];
 77	
 78	    for (const orb of this.yeoijus) {
 79	      orb.y += fallDelta;
 80	      orb.gfx.setPosition(orb.x, orb.y);
 81	
 82	      const dx = player.x - orb.x;
 83	      const dy = player.y - orb.y;
 84	      if (dx * dx + dy * dy < r2) {
 85	        this._collectYeoiju(orb, api);
 86	        continue;
 87	      }
 88	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
 89	      remaining.push(orb);
 90	    }
 91	    this.yeoijus = remaining;
 92	  }
 93	
 94	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
 95	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
 96	    orb.gfx.destroy();
 97	
 98	    if (this.isGoldForm) {
 99	      // 변신 후: 수집마다 벼락
100	      this._strikeThunder(api);
101	      return;
102	    }
103	
104	    this.yeoijuCount++;
105	    this._updateCounter();
106	
107	    if (this.yeoijuCount >= MUGI_PARAMS.goldThreshold) {
108	      this._transformGold(api);
109	    } else if (this.yeoijuCount % MUGI_PARAMS.redLightningEvery === 0) {
110	      this._strikeRedLightning(api);
111	    }
112	  }
113	
114	  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
115	    for (let i = 0; i < 6; i++) {
116	      const angle = (i / 6) * Math.PI * 2;
117	      const g = scene.add.graphics().setDepth(160);
118	      g.fillStyle(0xff3333, 1);
119	      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
120	      g.setPosition(x, y);
121	      scene.tweens.add({
122	        targets: g,
123	        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
124	        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
125	        alpha: 0, scale: 0,
126	        duration: Phaser.Math.Between(200, 360),
127	        ease: 'Quad.easeOut',
128	        onComplete: () => g.destroy(),
129	      });
130	    }
131	  }
132	
133	  private _updateCounter(): void {
134	    if (!this.counterText) return;
135	    this.counterText.setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.goldThreshold}`);
136	  }
137	
138	  // ── 황금 변신 (1회성) ────────────────────────────────────────────────
139	
140	  private _transformGold(api: GameSceneAPI): void {
141	    this.isGoldForm = true;
142	
143	    this.yeoijus.forEach(orb => orb.gfx.destroy());
144	    this.yeoijus = [];
145	    this.counterText?.setVisible(false);
146	
147	    this._strikeThunder(api);
148	  }
149	
150	  private _strikeThunder(api: GameSceneAPI): void {
151	    const { scene, player } = api;
152	    const tx = player.x;
153	    const ty = player.y;
154	
155	    // 강한 노란 플래시
156	    scene.cameras.main.flash(600, 255, 230, 0, true);
157	
158	    // 번개 Graphics
159	    const g = scene.add.graphics().setDepth(310);
160	
161	    // 수렴형 지그재그 포인트 생성 (위는 넓게 퍼지고 아래로 갈수록 tx로 수렴)
162	    const makePts = (startX: number) => {
163	      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
164	      for (let i = 1; i < 17; i++) {
165	        const t = i / 17;
166	        const spread = 70 * (1 - t * 0.65); // 위에서 넓고 아래로 수렴
167	        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
168	      }
169	      pts.push({ x: tx, y: ty + 8 });
170	      return pts;
171	    };
172	
173	    const drawBolt = () => {
174	      g.clear();
175	      const pts = makePts(tx + Phaser.Math.Between(-25, 25));
176	
177	      // 4중 글로우 레이어
178	      g.lineStyle(44, 0xffaa00, 0.09); this._drawPolyline(g, pts);
179	      g.lineStyle(22, 0xffcc00, 0.32); this._drawPolyline(g, pts);
180	      g.lineStyle(9,  0xffee44, 0.80); this._drawPolyline(g, pts);
181	      g.lineStyle(3,  0xffffff, 1.00); this._drawPolyline(g, pts);
182	
183	      // 가지 3개 — 각각 꺾이는 지그재그
184	      [3, 7, 11].forEach(bi => {
185	        if (bi >= pts.length - 1) return;
186	        const bp = pts[bi]!;
187	        const dir = Math.random() < 0.5 ? 1 : -1;
188	        const len = Phaser.Math.Between(55, 105);
189	        const bPts = [
