1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { MUGI_PARAMS } from '../config/abilityParams';
6	
7	interface YeoijuOrb {
8	  gfx: Phaser.GameObjects.Graphics;
9	  x: number;
10	  y: number;
11	}
12	
13	export class MugiAbility extends BaseAbility {
14	  private lastYeoijuScore = 0;
15	  private yeoijuCount     = 0;
16	  private yeoijus: YeoijuOrb[] = [];
17	  private counterText: Phaser.GameObjects.Text | null = null;
18	  private normalPrefix    = 'mugi_';
19	  private isGoldForm      = false;
20	
21	  override onCreate(api: GameSceneAPI): void {
22	    this.lastYeoijuScore = 0;
23	    this.yeoijuCount     = 0;
24	    this.yeoijus         = [];
25	    this.counterText     = null;
26	    this.normalPrefix    = api.player.getTexturePrefix();
27	    this.isGoldForm      = false;
28	
29	    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.goldThreshold}`, {
30	      fontSize: '11px',
31	      color: '#ff88cc',
32	      stroke: '#000000',
33	      strokeThickness: 3,
34	    }).setDepth(500).setAlpha(0.88);
35	  }
36	
37	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
38	    const interval = this.isGoldForm ? MUGI_PARAMS.yeoijuGoldInterval : MUGI_PARAMS.yeoijuInterval;
39	    if (score % interval === 0 && score > this.lastYeoijuScore) {
40	      this.lastYeoijuScore = score;
41	      this._spawnYeoiju(api);
42	    }
43	  }
44	
45	  override onUpdate(api: GameSceneAPI): void {
46	    this._updateYeoijus(api);
47	  }
48	
49	  // ── 여의주 ──────────────────────────────────────────────────────────
50	
51	  private _spawnYeoiju(api: GameSceneAPI): void {
52	    const scene = api.scene;
53	    const x = Phaser.Math.Between(30, 370);
54	
55	    const gfx = scene.add.graphics().setDepth(150);
56	    gfx.fillStyle(0xff2222, 0.12); gfx.fillCircle(0, 0, 20);
57	    gfx.fillStyle(0xff2222, 0.38); gfx.fillCircle(0, 0, 13);
58	    gfx.fillStyle(0xff3333, 1);    gfx.fillCircle(0, 0, 8);
59	    gfx.fillStyle(0xff9999, 0.85); gfx.fillCircle(0, 0, 5);
60	    gfx.fillStyle(0xffffff, 0.75); gfx.fillCircle(-2.5, -3, 2.2);
61	    gfx.setPosition(x, -20);
62	
63	    scene.tweens.add({
64	      targets: gfx, alpha: { from: 0.72, to: 1 },
65	      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
66	    });
67	
68	    this.yeoijus.push({ gfx, x, y: -20 });
69	  }
70	
71	  private _updateYeoijus(api: GameSceneAPI): void {
72	    const delta = api.scene.game.loop.delta * 0.001;
73	    const { player } = api;
74	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
75	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
76	    const remaining: YeoijuOrb[] = [];
77	
78	    for (const orb of this.yeoijus) {
79	      orb.y += fallDelta;
80	      orb.gfx.setPosition(orb.x, orb.y);
81	
82	      const dx = player.x - orb.x;
83	      const dy = player.y - orb.y;
84	      if (dx * dx + dy * dy < r2) {
85	        this._collectYeoiju(orb, api);
86	        continue;
87	      }
88	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
89	      remaining.push(orb);
90	    }
91	    this.yeoijus = remaining;
92	  }
93	
94	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
95	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
96	    orb.gfx.destroy();
97	
98	    if (this.isGoldForm) {
99	      this._strikeThunder(api);
100	      return;
101	    }
102	
103	    this.yeoijuCount++;
104	    this._updateCounter();
105	
106	    if (this.yeoijuCount >= MUGI_PARAMS.goldThreshold) {
107	      this._transformGold(api);
108	    } else {
109	      this._strikeRedLightning(api);
110	    }
111	  }
112	
113	  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
114	    for (let i = 0; i < 6; i++) {
115	      const angle = (i / 6) * Math.PI * 2;
116	      const g = scene.add.graphics().setDepth(160);
117	      g.fillStyle(0xff3333, 1);
118	      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
119	      g.setPosition(x, y);
120	      scene.tweens.add({
121	        targets: g,
122	        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
123	        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
124	        alpha: 0, scale: 0,
125	        duration: Phaser.Math.Between(200, 360),
126	        ease: 'Quad.easeOut',
127	        onComplete: () => g.destroy(),
128	      });
129	    }
130	  }
131	
132	  private _updateCounter(): void {
133	    if (!this.counterText) return;
134	    this.counterText.setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.goldThreshold}`);
135	  }
136	
137	  // ── 황금 변신 (1회성) ────────────────────────────────────────────────
138	
139	  private _transformGold(api: GameSceneAPI): void {
140	    this.isGoldForm = true;
141	
142	    this.yeoijus.forEach(orb => orb.gfx.destroy());
143	    this.yeoijus = [];
144	    this.counterText?.setVisible(false);
145	
146	    this._strikeThunder(api);
147	  }
148	
149	  private _strikeThunder(api: GameSceneAPI): void {
150	    const { scene, player } = api;
151	    const tx = player.x;
152	    const ty = player.y;
153	
154	    // 강한 노란 플래시
155	    scene.cameras.main.flash(600, 255, 230, 0, true);
156	
157	    // 번개 Graphics
158	    const g = scene.add.graphics().setDepth(310);
159	
160	    // 수렴형 지그재그 포인트 생성 (위는 넓게 퍼지고 아래로 갈수록 tx로 수렴)
161	    const makePts = (startX: number) => {
162	      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
163	      for (let i = 1; i < 17; i++) {
164	        const t = i / 17;
165	        const spread = 70 * (1 - t * 0.65); // 위에서 넓고 아래로 수렴
166	        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
167	      }
168	      pts.push({ x: tx, y: ty + 8 });
169	      return pts;
170	    };
171	
172	    const drawBolt = () => {
173	      g.clear();
174	      const pts = makePts(tx + Phaser.Math.Between(-25, 25));
175	
176	      // 4중 글로우 레이어
177	      g.lineStyle(44, 0xffaa00, 0.09); this._drawPolyline(g, pts);
178	      g.lineStyle(22, 0xffcc00, 0.32); this._drawPolyline(g, pts);
179	      g.lineStyle(9,  0xffee44, 0.80); this._drawPolyline(g, pts);
180	      g.lineStyle(3,  0xffffff, 1.00); this._drawPolyline(g, pts);
181	
182	      // 가지 3개 — 각각 꺾이는 지그재그
183	      [3, 7, 11].forEach(bi => {
184	        if (bi >= pts.length - 1) return;
185	        const bp = pts[bi]!;
186	        const dir = Math.random() < 0.5 ? 1 : -1;
187	        const len = Phaser.Math.Between(55, 105);
188	        const bPts = [
189	          { x: bp.x, y: bp.y },
190	          { x: bp.x + dir * len * 0.35 + Phaser.Math.Between(-18, 18), y: bp.y + len * 0.33 },
191	          { x: bp.x + dir * len * 0.68 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.65 },
192	          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
193	        ];
194	        g.lineStyle(9,  0xffcc00, 0.40); this._drawPolyline(g, bPts);
195	        g.lineStyle(3,  0xffee44, 0.75); this._drawPolyline(g, bPts);
196	        g.lineStyle(1.5, 0xffffff, 0.90); this._drawPolyline(g, bPts);
197	      });
198	    };
199	
200	    // 5회 재그림 (50ms 간격) — 지글 효과
201	    drawBolt();
202	    [50, 100, 150, 200].forEach(delay => {
203	      scene.time.delayedCall(delay, () => {
204	        if (!scene.sys.isActive() || !g.active) return;
205	        drawBolt();
206	      });
207	    });
208	
209	    // 번개 페이드아웃
210	    scene.tweens.add({
211	      targets: g, alpha: 0, delay: 240, duration: 380, ease: 'Quad.easeOut',
212	      onComplete: () => g.destroy(),
213	    });
214	
215	    // 착탄 임팩트 원
216	    const impact = scene.add.graphics().setDepth(308);
217	    impact.fillStyle(0xffee00, 0.7);
218	    impact.fillCircle(tx, ty, 55);
219	    scene.tweens.add({
220	      targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
221	      duration: 500, ease: 'Quad.easeOut',
222	      onComplete: () => impact.destroy(),
223	    });
224	
225	    // 착탄 링
226	    const ring = scene.add.graphics().setDepth(309);
227	    ring.lineStyle(4, 0xffffff, 1);
228	    ring.strokeCircle(tx, ty, 40);
229	    scene.tweens.add({
230	      targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
231	      duration: 450, ease: 'Quad.easeOut',
232	      onComplete: () => ring.destroy(),
233	    });
234	
235	    scene.time.delayedCall(180, () => {
236	      if (!scene.sys.isActive()) return;
237	      api.player.setTexturePrefix('gold_mugi_');
238	      this._clearPoops(api, () => true, 10);
239	    });
240	  }
241	
242	  // ── 변신 전 — 검붉은 번개 (시각 효과만) ────────────────────────────
243	
244	  private _strikeRedLightning(api: GameSceneAPI): void {
245	    const { scene, player } = api;
246	    const tx = player.x;
247	    const ty = player.y;
248	
249	    scene.cameras.main.flash(250, 120, 0, 0, true);
250	
251	    const g = scene.add.graphics().setDepth(310);
252	
253	    const makeRedPts = (startX: number) => {
254	      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
255	      for (let i = 1; i < 14; i++) {
256	        const t = i / 14;
257	        const spread = 55 * (1 - t * 0.6);
258	        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
259	      }
260	      pts.push({ x: tx, y: ty + 8 });
261	      return pts;
262	    };
263	
264	    const drawRed = () => {
265	      g.clear();
266	      const pts = makeRedPts(tx + Phaser.Math.Between(-20, 20));
267	
268	      g.lineStyle(36, 0x550000, 0.12); this._drawPolyline(g, pts);
269	      g.lineStyle(16, 0x990000, 0.40); this._drawPolyline(g, pts);
270	      g.lineStyle(7,  0xcc2200, 0.85); this._drawPolyline(g, pts);
271	      g.lineStyle(2.5, 0xff6644, 1.00); this._drawPolyline(g, pts);
272	
273	      // 가지 2개
274	      [3, 8].forEach(bi => {
275	        if (bi >= pts.length - 1) return;
276	        const bp = pts[bi]!;
277	        const dir = Math.random() < 0.5 ? 1 : -1;
278	        const len = Phaser.Math.Between(40, 80);
279	        const bPts = [
280	          { x: bp.x, y: bp.y },
281	          { x: bp.x + dir * len * 0.4 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.4 },
282	          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
283	        ];
284	        g.lineStyle(6,  0xaa1100, 0.45); this._drawPolyline(g, bPts);
285	        g.lineStyle(2,  0xff4422, 0.80); this._drawPolyline(g, bPts);
286	      });
287	    };
288	
289	    drawRed();
290	    [55, 110, 165].forEach(delay => {
291	      scene.time.delayedCall(delay, () => {
292	        if (!scene.sys.isActive() || !g.active) return;
293	        drawRed();
294	      });
295	    });
296	
297	    scene.tweens.add({
298	      targets: g, alpha: 0, delay: 210, duration: 300, ease: 'Quad.easeOut',
299	      onComplete: () => g.destroy(),
300	    });
301	
302	    // 작은 착탄 임팩트
303	    const impact = scene.add.graphics().setDepth(308);
304	    impact.fillStyle(0xaa0000, 0.55);
305	    impact.fillCircle(tx, ty, 35);
306	    scene.tweens.add({
307	      targets: impact, scaleX: 2.2, scaleY: 2.2, alpha: 0,
308	      duration: 380, ease: 'Quad.easeOut',
309	      onComplete: () => impact.destroy(),
310	    });
311	
312	    scene.time.delayedCall(180, () => {
313	      if (!scene.sys.isActive()) return;
314	      this._clearPoops(api, p => Math.abs(p.x - tx) <= 60, 5);
315	    });
316	  }
317	
318	  private _clearPoops(
319	    api: GameSceneAPI,
320	    filter: (p: Phaser.Physics.Arcade.Sprite) => boolean,
321	    pointsPerPoop: number,
322	  ): void {
323	    const { poops, scene } = api;
324	
325	    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
326	      .filter(p => p.active && filter(p));
327	
328	    if (targets.length === 0) return;
329	
330	    targets.forEach(p => {
331	      const body = p.body as Phaser.Physics.Arcade.Body;
332	      body.setVelocityY(0);
333	      body.setEnable(false);
334	      this._spawnZapEffect(p.x, p.y, scene);
335	    });
336	
337	    scene.time.delayedCall(450, () => {
338	      if (!scene.sys.isActive()) return;
339	      targets.forEach(p => {
340	        if (p.active) (p as unknown as PoolablePoopBase).recycle();
341	      });
342	      api.addAbilityBonus(targets.length * pointsPerPoop);
343	    });
344	  }
345	
346	  private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
347	    g.beginPath();
348	    g.moveTo(pts[0]!.x, pts[0]!.y);
349	    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
350	    g.strokePath();
351	  }
352	
353	  private _spawnZapEffect(x: number, y: number, scene: Phaser.Scene): void {
354	    const g = scene.add.graphics().setDepth(206);
355	
356	    const draw = () => {
357	      g.clear();
358	      const sparks = Phaser.Math.Between(3, 5);
