import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MUGI_PARAMS } from '../config/abilityParams';

interface YeoijuOrb {
  gfx: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
}

export class MugiAbility extends BaseAbility {
  private lastYeoijuScore = 0;
  private yeoijuCount     = 0;
  private yeoijus: YeoijuOrb[] = [];
  private counterText: Phaser.GameObjects.Text | null = null;
  private normalPrefix    = 'mugi_';
  private isGoldForm      = false;

  override onCreate(api: GameSceneAPI): void {
    this.lastYeoijuScore = 0;
    this.yeoijuCount     = 0;
    this.yeoijus         = [];
    this.counterText     = null;
    this.normalPrefix    = api.player.getTexturePrefix();
    this.isGoldForm      = false;

    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.goldThreshold}`, {
      fontSize: '11px',
      color: '#ff88cc',
      stroke: '#000000',
      strokeThickness: 3,
    }).setDepth(500).setAlpha(0.88);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    const interval = this.isGoldForm ? MUGI_PARAMS.yeoijuGoldInterval : MUGI_PARAMS.yeoijuInterval;
    if (score % interval === 0 && score > this.lastYeoijuScore) {
      this.lastYeoijuScore = score;
      this._spawnYeoiju(api);
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    this._updateYeoijus(api);
  }

  // ── 여의주 ──────────────────────────────────────────────────────────

  private _spawnYeoiju(api: GameSceneAPI): void {
    const scene = api.scene;
    const x = Phaser.Math.Between(30, 370);

    const gfx = scene.add.graphics().setDepth(150);
    gfx.fillStyle(0xff2222, 0.12); gfx.fillCircle(0, 0, 20);
    gfx.fillStyle(0xff2222, 0.38); gfx.fillCircle(0, 0, 13);
    gfx.fillStyle(0xff3333, 1);    gfx.fillCircle(0, 0, 8);
    gfx.fillStyle(0xff9999, 0.85); gfx.fillCircle(0, 0, 5);
    gfx.fillStyle(0xffffff, 0.75); gfx.fillCircle(-2.5, -3, 2.2);
    gfx.setPosition(x, -20);

    scene.tweens.add({
      targets: gfx, alpha: { from: 0.72, to: 1 },
      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
    });

    this.yeoijus.push({ gfx, x, y: -20 });
  }

  private _updateYeoijus(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta * 0.001;
    const { player } = api;
    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
    const remaining: YeoijuOrb[] = [];

    for (const orb of this.yeoijus) {
      orb.y += fallDelta;
      orb.gfx.setPosition(orb.x, orb.y);

      const dx = player.x - orb.x;
      const dy = player.y - orb.y;
      if (dx * dx + dy * dy < r2) {
        this._collectYeoiju(orb, api);
        continue;
      }
      if (orb.y > 660) { orb.gfx.destroy(); continue; }
      remaining.push(orb);
    }
    this.yeoijus = remaining;
  }

  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
    this._spawnCollectEffect(orb.x, orb.y, api.scene);
    orb.gfx.destroy();

    if (this.isGoldForm) {
      this._strikeThunder(api);
      return;
    }

    this.yeoijuCount++;
    this._updateCounter();

    if (this.yeoijuCount >= MUGI_PARAMS.goldThreshold) {
      this._transformGold(api);
    } else {
      this._strikeRedLightning(api);
    }
  }

  private _spawnCollectEffect(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const g = scene.add.graphics().setDepth(160);
      g.fillStyle(0xff3333, 1);
      g.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      g.setPosition(x, y);
      scene.tweens.add({
        targets: g,
        x: x + Math.cos(angle) * Phaser.Math.Between(12, 28),
        y: y + Math.sin(angle) * Phaser.Math.Between(12, 28),
        alpha: 0, scale: 0,
        duration: Phaser.Math.Between(200, 360),
        ease: 'Quad.easeOut',
        onComplete: () => g.destroy(),
      });
    }
  }

  private _updateCounter(): void {
    if (!this.counterText) return;
    this.counterText.setText(`여의주 ${this.yeoijuCount}/${MUGI_PARAMS.goldThreshold}`);
  }

  // ── 황금 변신 (1회성) ────────────────────────────────────────────────

  private _transformGold(api: GameSceneAPI): void {
    this.isGoldForm = true;

    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.setVisible(false);

    this._strikeThunder(api);
  }

  private _strikeThunder(api: GameSceneAPI): void {
    const { scene, player } = api;
    const tx = player.x;
    const ty = player.y;

    // 강한 노란 플래시
    scene.cameras.main.flash(600, 255, 230, 0, true);

    // 번개 Graphics
    const g = scene.add.graphics().setDepth(310);

    // 수렴형 지그재그 포인트 생성 (위는 넓게 퍼지고 아래로 갈수록 tx로 수렴)
    const makePts = (startX: number) => {
      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
      for (let i = 1; i < 17; i++) {
        const t = i / 17;
        const spread = 70 * (1 - t * 0.65); // 위에서 넓고 아래로 수렴
        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
      }
      pts.push({ x: tx, y: ty + 8 });
      return pts;
    };

    const drawBolt = () => {
      g.clear();
      const pts = makePts(tx + Phaser.Math.Between(-25, 25));

      // 4중 글로우 레이어
      g.lineStyle(44, 0xffaa00, 0.09); this._drawPolyline(g, pts);
      g.lineStyle(22, 0xffcc00, 0.32); this._drawPolyline(g, pts);
      g.lineStyle(9,  0xffee44, 0.80); this._drawPolyline(g, pts);
      g.lineStyle(3,  0xffffff, 1.00); this._drawPolyline(g, pts);

      // 가지 3개 — 각각 꺾이는 지그재그
      [3, 7, 11].forEach(bi => {
        if (bi >= pts.length - 1) return;
        const bp = pts[bi]!;
        const dir = Math.random() < 0.5 ? 1 : -1;
        const len = Phaser.Math.Between(55, 105);
        const bPts = [
          { x: bp.x, y: bp.y },
          { x: bp.x + dir * len * 0.35 + Phaser.Math.Between(-18, 18), y: bp.y + len * 0.33 },
          { x: bp.x + dir * len * 0.68 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.65 },
          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
        ];
        g.lineStyle(9,  0xffcc00, 0.40); this._drawPolyline(g, bPts);
        g.lineStyle(3,  0xffee44, 0.75); this._drawPolyline(g, bPts);
        g.lineStyle(1.5, 0xffffff, 0.90); this._drawPolyline(g, bPts);
      });
    };

    // 5회 재그림 (50ms 간격) — 지글 효과
    drawBolt();
    [50, 100, 150, 200].forEach(delay => {
      scene.time.delayedCall(delay, () => {
        if (!scene.sys.isActive() || !g.active) return;
        drawBolt();
      });
    });

    // 번개 페이드아웃
    scene.tweens.add({
      targets: g, alpha: 0, delay: 240, duration: 380, ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    });

    // 착탄 임팩트 원
    const impact = scene.add.graphics().setDepth(308);
    impact.fillStyle(0xffee00, 0.7);
    impact.fillCircle(tx, ty, 55);
    scene.tweens.add({
      targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
      duration: 500, ease: 'Quad.easeOut',
      onComplete: () => impact.destroy(),
    });

    // 착탄 링
    const ring = scene.add.graphics().setDepth(309);
    ring.lineStyle(4, 0xffffff, 1);
    ring.strokeCircle(tx, ty, 40);
    scene.tweens.add({
      targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
      duration: 450, ease: 'Quad.easeOut',
      onComplete: () => ring.destroy(),
    });

    scene.time.delayedCall(180, () => {
      if (!scene.sys.isActive()) return;
      api.player.setTexturePrefix('gold_mugi_');
      this._clearPoops(api, () => true, 10);
    });
  }

  // ── 변신 전 — 검붉은 번개 (시각 효과만) ────────────────────────────

  private _strikeRedLightning(api: GameSceneAPI): void {
    const { scene, player } = api;
    const tx = player.x;
    const ty = player.y;

    scene.cameras.main.flash(250, 120, 0, 0, true);

    const g = scene.add.graphics().setDepth(310);

    const makeRedPts = (startX: number) => {
      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
      for (let i = 1; i < 14; i++) {
        const t = i / 14;
        const spread = 55 * (1 - t * 0.6);
        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
      }
      pts.push({ x: tx, y: ty + 8 });
      return pts;
    };

    const drawRed = () => {
      g.clear();
      const pts = makeRedPts(tx + Phaser.Math.Between(-20, 20));

      g.lineStyle(36, 0x550000, 0.12); this._drawPolyline(g, pts);
      g.lineStyle(16, 0x990000, 0.40); this._drawPolyline(g, pts);
      g.lineStyle(7,  0xcc2200, 0.85); this._drawPolyline(g, pts);
      g.lineStyle(2.5, 0xff6644, 1.00); this._drawPolyline(g, pts);

      // 가지 2개
      [3, 8].forEach(bi => {
        if (bi >= pts.length - 1) return;
        const bp = pts[bi]!;
        const dir = Math.random() < 0.5 ? 1 : -1;
        const len = Phaser.Math.Between(40, 80);
        const bPts = [
          { x: bp.x, y: bp.y },
          { x: bp.x + dir * len * 0.4 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.4 },
          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
        ];
        g.lineStyle(6,  0xaa1100, 0.45); this._drawPolyline(g, bPts);
        g.lineStyle(2,  0xff4422, 0.80); this._drawPolyline(g, bPts);
      });
    };

    drawRed();
    [55, 110, 165].forEach(delay => {
      scene.time.delayedCall(delay, () => {
        if (!scene.sys.isActive() || !g.active) return;
        drawRed();
      });
    });

    scene.tweens.add({
      targets: g, alpha: 0, delay: 210, duration: 300, ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    });

    // 작은 착탄 임팩트
    const impact = scene.add.graphics().setDepth(308);
    impact.fillStyle(0xaa0000, 0.55);
    impact.fillCircle(tx, ty, 35);
    scene.tweens.add({
      targets: impact, scaleX: 2.2, scaleY: 2.2, alpha: 0,
      duration: 380, ease: 'Quad.easeOut',
      onComplete: () => impact.destroy(),
    });

    scene.time.delayedCall(180, () => {
      if (!scene.sys.isActive()) return;
      this._clearPoops(api, p => Math.abs(p.x - tx) <= 60, 5);
    });
  }

  private _clearPoops(
    api: GameSceneAPI,
    filter: (p: Phaser.Physics.Arcade.Sprite) => boolean,
    pointsPerPoop: number,
  ): void {
    const { poops, scene } = api;

    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && filter(p));

    if (targets.length === 0) return;

    targets.forEach(p => {
      const body = p.body as Phaser.Physics.Arcade.Body;
      body.setVelocityY(0);
      body.setEnable(false);
      this._spawnZapEffect(p.x, p.y, scene);
    });

    scene.time.delayedCall(450, () => {
      if (!scene.sys.isActive()) return;
      targets.forEach(p => {
        if (p.active) (p as unknown as PoolablePoopBase).recycle();
      });
      api.addAbilityBonus(targets.length * pointsPerPoop);
    });
  }

  private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
    g.beginPath();
    g.moveTo(pts[0]!.x, pts[0]!.y);
    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
    g.strokePath();
  }

  private _spawnZapEffect(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics().setDepth(206);

    const draw = () => {
      g.clear();
      const sparks = Phaser.Math.Between(3, 5);
      for (let i = 0; i < sparks; i++) {
        const color = Math.random() < 0.55 ? 0xffee00 : 0xffffff;
        g.lineStyle(Phaser.Math.FloatBetween(1.5, 2.5), color, 1);
        g.beginPath();
        let px = x + Phaser.Math.Between(-7, 7);
        let py = y + Phaser.Math.Between(-7, 7);
        g.moveTo(px, py);
        for (let j = 0; j < 3; j++) {
          px += Phaser.Math.Between(-10, 10);
          py += Phaser.Math.Between(-10, 10);
          g.lineTo(px, py);
        }
        g.strokePath();
      }
    };

    draw();

    // 80ms마다 재그림
    const timer = scene.time.addEvent({ delay: 80, repeat: 5, callback: draw });

    // 550ms 후 정리 (제거 시점인 450ms 이후까지 잠깐 유지)
    scene.time.delayedCall(550, () => {
      timer.remove();
      if (g.active) g.destroy();
    });
  }

  // ── 정리 ────────────────────────────────────────────────────────────

  override onDestroy(api: GameSceneAPI): void {
    this.yeoijus.forEach(orb => orb.gfx.destroy());
    this.yeoijus = [];
    this.counterText?.destroy();
    this.counterText = null;
    if (this.isGoldForm) {
      api.player.setTexturePrefix(this.normalPrefix);
      this.isGoldForm = false;
    }
  }
}

/**
 * 캐릭터 능력 수치 설정 (단일 진실 공급원)
 *
 * PARAMS  — 능력 클래스에서 사용하는 숫자/비율 값
 * DESC    — PARAMS로 자동 생성되는 설명 문자열 (character.ts에서 import)
 *
 * 수치를 바꾸면 게임 로직과 캐릭터 정보 패널이 동시에 갱신됩니다.
 */

// ── 루트 (Hacker / SR) ────────────────────────────────────────────────
export const HACKER_PARAMS = {
  deleteInterval: 100,      // 터미널 삭제 점수 간격
  deleteCount: 7,           // 삭제하는 똥 개수
  specialPoopSlowdown: 40,  // 특수 똥 낙하 속도 감소 (px/s)
} as const;

export const HACKER_DESC = {
  basicEffect: '금똥·다이아똥 낙하 속도 감소',
  specialAbility: `${HACKER_PARAMS.deleteInterval}점마다 일반 똥 ${HACKER_PARAMS.deleteCount}개 터미널 삭제`,
} as const;

// ── 광부 (Miner / SR) ─────────────────────────────────────────────────
export const MINER_PARAMS = {
  specialBonus: 5,         // 특수 똥 수집 시 추가 점수
  rainbowInterval: 350,     // 무지개똥 생성 점수 간격
} as const;

export const MINER_DESC = {
  basicEffect: `특수 똥 수집 시 +${MINER_PARAMS.specialBonus}점 추가`,
  specialAbility: `${MINER_PARAMS.rainbowInterval}점마다 무지개똥 생성`,
} as const;

// ── 매화 (Maehwa / SR) ────────────────────────────────────────────────
export const MAEHWA_PARAMS = {
  speedBonus: 50,           // 이동 속도 보너스 (px/s)
  slashInterval: 100,       // 칼 베기 점수 간격
  slashCount: 3,            // 한 번에 베는 똥 개수
  awake2SpecialBonus: 5,    // ★2+ 특수 똥 수집 추가 점수
  synergyBurstInterval: 2000,
  synergyBurstBonus: 150,    // 매화×매화 버스트 발동 시 고정 보너스 점수
} as const;

export const MAEHWA_DESC = {
  basicEffect: `이동 속도 +${MAEHWA_PARAMS.speedBonus}px/s`,
  specialAbility: `${MAEHWA_PARAMS.slashInterval}점마다 위쪽 똥 ${MAEHWA_PARAMS.slashCount}개 칼로 제거`,
} as const;

// ── 아카이브 (Archieve / SR) ──────────────────────────────────────────
export const ARCHIEVE_PARAMS = {
  scoreMultiplierExtra: 0.10, // 점수 배율 추가분 (base의 10% → 1.1배)
  bonusInterval: 200,         // 보너스 점수 간격
  bonusScore: 20,             // 보너스 점수
} as const;

export const ARCHIEVE_DESC = {
  basicEffect: `점수 획득 속도 ${1 + ARCHIEVE_PARAMS.scoreMultiplierExtra}배`,
  specialAbility: `${ARCHIEVE_PARAMS.bonusInterval}점마다 +${ARCHIEVE_PARAMS.bonusScore}점 보너스`,
} as const;

// ── 글리치 (Glitch / SR) ──────────────────────────────────────────────
export const GLITCH_PARAMS = {
  collectInterval: 200,     // 분신 소환 점수 간격
  collectCount: 1,          // 분신이 한 번에 수집하는 특수 똥 개수
} as const;

export const GLITCH_DESC = {
  basicEffect: '잔상 분신이 특수 똥 수집',
  specialAbility: `${GLITCH_PARAMS.collectInterval}점마다 특수 똥 위치에 분신 소환`,
} as const;

// ── 노이즈 (Noise / SR) ───────────────────────────────────────────────
export const NOISE_PARAMS = {
  spawnShortening: 0.25,    // 특수 똥 생성 주기 단축 비율 (25%)
  reductionInterval: 200,   // 소환 감소 점수 간격
  reductionAmount: 2,       // 소환 감소 개수
  goldInterval: 30,         // 금똥 생성 간격 (기본 40의 75%)
  diamondInterval: 75,      // 다이아똥 생성 간격 (기본 100의 75%)
  topazInterval: 135,       // 토파즈똥 생성 간격 (기본 180의 75%)
} as const;

export const NOISE_DESC = {
  basicEffect: `특수 똥 생성 주기 ${NOISE_PARAMS.spawnShortening * 100}% 단축`,
  specialAbility: `${NOISE_PARAMS.reductionInterval}점마다 다음 소환 ${NOISE_PARAMS.reductionAmount}개 감소`,
} as const;

// ── 센티넬 (Sentinel / UR) ────────────────────────────────────────────
export const SENTINEL_PARAMS = {
  startShields: 2,          // 시작 보호막 개수
  chargeInterval: 300,      // 보호막 충전 점수 간격
  maxShields: 3,            // 최대 보호막 개수
} as const;

export const SENTINEL_DESC = {
  basicEffect: `시작 시 보호막 ${SENTINEL_PARAMS.startShields}개 보유 (피격 흡수 시 주변 똥 전기로 제거, 제거된 똥 1개당 +10점)`,
  specialAbility: `${SENTINEL_PARAMS.chargeInterval}점마다 보호막 1개 충전 (최대 ${SENTINEL_PARAMS.maxShields}개)`,
} as const;

// ── 나이트 (Knight / SR) ──────────────────────────────────────────────
export const KNIGHT_PARAMS = {
  beamKillBonus: 1,        // 검기로 제거한 일반 똥 1개당 추가 점수
  beamInterval: 100,       // 검기 발사 점수 간격
} as const;

export const KNIGHT_DESC = {
  basicEffect: `검기로 제거한 일반 똥 1개당 +${KNIGHT_PARAMS.beamKillBonus}점`,
