    const g = scene.add.graphics().setDepth(353 + depthOff);
    g.fillStyle(color, 0.92); g.fillEllipse(0, 0, w, h);
    g.fillStyle(0xffffff, 0.45); g.fillEllipse(0, 0, w * 0.35, h * 0.65);
    g.fillStyle(0xffd700, 0.18); g.fillEllipse(0, -(h * 0.3), w * 0.55, h * 0.22);
    g.lineStyle(1, 0xffc0d0, 0.4); g.strokeEllipse(0, 0, w, h);
    g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);

    scene.tweens.add({ targets: g, scale: 1, delay: idx * 40, duration: 280, ease: 'Back.easeOut' });
    petalGfxs.push(g);
  });

  // 수술
  const stamen = scene.add.graphics().setDepth(359).setScale(0);
  stamen.fillStyle(0xffd700, 1); stamen.fillCircle(0, 0, 5);
  stamen.fillStyle(0xffff99, 0.9); stamen.fillCircle(0, 0, 3);
  stamen.fillStyle(0xffffff, 0.7); stamen.fillCircle(-1, -1.5, 1.5);
  stamen.setPosition(cx, cy - 20);
  scene.tweens.add({
    targets: stamen, scale: 1,
    delay: LOTUS_DEFS.length * 40 - 20, duration: 220, ease: 'Back.easeOut',
  });

  // 900ms 후 조용히 페이드아웃 (폭발 없이)
  const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base, stamen];
  scene.time.delayedCall(900, () => {
    if (!scene.sys.isActive()) return;
    allObjs.forEach(obj => {
      scene.tweens.add({
        targets: obj, alpha: 0,
        duration: 500, ease: 'Quad.easeIn',
        onComplete: () => { if (obj.active) obj.destroy(); },
      });
    });
  });
}

