  // 금빛 중앙 글로우
  const glow = scene.add.graphics().setDepth(353).setScale(0);
  glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 30);
  glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 18);
  glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0, 8);
  glow.setPosition(cx, cy - 14);
  scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });

