  glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0, 8);
  glow.setPosition(cx, cy - 14);
  scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });

