// ── 기운 (아우라) 이펙트 ─────────────────────────────────────────────

private _tickAura(api: GameSceneAPI): void {
  // 변신 전: 10개마다 레벨 1씩 증가 (1~4), 변신 후: 레벨 5 (금색)
  const level = this.isGoldForm ? 5 : Math.floor(this.yeoijuCount / 10);
  if (level === 0) return;

  const delta = api.scene.game.loop.delta;
  this.auraTimer += delta;
  // 레벨이 높을수록 빠르게 생성: 1→330ms, 2→260ms, 3→190ms, 4→120ms, 5→70ms
  const interval = Math.max(70, 400 - level * 70);
  if (this.auraTimer < interval) return;
  this.auraTimer -= interval;

  // 레벨마다 파티클 수 증가 (1개→2개→3개→4개→5개)
  for (let i = 0; i < level; i++) {
    this._spawnAuraWisp(api.player.x, api.player.y, this.isGoldForm, level, api.scene);
  }
}

private _spawnAuraWisp(px: number, py: number, isGold: boolean, level: number, scene: Phaser.Scene): void {
  const angle  = Math.random() * Math.PI * 2;
  const spread = 18 + level * 4;
  const ox = px + Math.cos(angle) * Phaser.Math.Between(8, spread);
  const oy = py + Math.sin(angle) * Phaser.Math.Between(8, spread * 0.6);
  const size = Phaser.Math.FloatBetween(3, 5 + level * 0.6);

  const g = scene.add.graphics().setDepth(6).setPosition(ox, oy);

  if (isGold) {
    g.fillStyle(0xffd700, 0.85); g.fillCircle(0, 0, size);
    g.fillStyle(0xffee88, 0.60); g.fillCircle(0, 0, size * 0.55);
    g.fillStyle(0xffffff, 0.50); g.fillCircle(0, 0, size * 0.28);
  } else {
    // 검은 기운: 짙은 보라-흑 + 내부 심홍 광채
    g.fillStyle(0x0a0016, 0.90); g.fillCircle(0, 0, size);
    g.fillStyle(0x440066, 0.55); g.fillCircle(0, 0, size * 0.62);
    g.fillStyle(0xcc00ff, 0.28); g.fillCircle(0, 0, size * 0.32);
  }

  scene.tweens.add({
    targets: g,
    y: oy - Phaser.Math.Between(22, 44),
    x: ox + Phaser.Math.Between(-14, 14),
    alpha: 0,
    scale: isGold ? 1.8 : 0.3,
    duration: Phaser.Math.Between(480, 860),
    ease: 'Quad.easeOut',
    onComplete: () => { if (g.active) g.destroy(); },
  });
}

