1	import Phaser from 'phaser';
2	import { RELEASE_NOTES } from '../data/releaseNotes';
3	import BaseScene from './BaseScene';
4	
5	export default class ReleaseNotesScene extends BaseScene {
6	  private scrollContainer!: Phaser.GameObjects.Container;
7	  private maskShape!: Phaser.GameObjects.Graphics;
8	  private scrollY: number = 0;
9	  private maxScrollY: number = 0;
10	  private isDragging: boolean = false;
11	  private dragStartY: number = 0;
12	  private dragStartScrollY: number = 0;
13	
14	  constructor() {
15	    super('ReleaseNotesScene');
16	  }
17	
18	  preload() {
19	    if (!this.textures.exists('background2')) {
20	      this.load.image('background2', 'assets/backgrounds/background2.webp');
21	    }
22	  }
23	
24	  create() {
25	    super.create();
26	
27	    const W = this.scale.width;
28	    const H = this.scale.height;
29	    const cx = W / 2;
30	    const yOff = (H - 600) / 2;
31	    const scrollTop = 70 + yOff;
32	    const scrollBottom = H - 60; // 뒤로가기 버튼 위
33	    const scrollHeight = scrollBottom - scrollTop;
34	
35	    this.scrollY = 0;
36	
37	    // 배경
38	    const background = this.add.image(cx, H / 2, 'background2');
39	    background.setDisplaySize(W, H);
40	
41	    // 반투명 오버레이 (더 어둡게)
42	    this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.7);
43	
44	    // 타이틀 (고정)
45	    this.add.text(cx, 35 + yOff, '릴리즈 노트', {
46	      fontSize: '26px',
47	      color: '#fff',
48	      fontStyle: 'bold',
49	      stroke: '#000',
50	      strokeThickness: 5,
51	    }).setOrigin(0.5).setDepth(10);
52	
53	    // 스크롤 영역 마스크
54	    this.maskShape = this.make.graphics({ x: 0, y: 0 });
55	    this.maskShape.fillRect(0, scrollTop, W, scrollHeight);
56	    const mask = this.maskShape.createGeometryMask();
57	    this.events.once('shutdown', () => { this.maskShape.destroy(); });
58	
59	    // 스크롤 컨테이너
60	    this.scrollContainer = this.add.container(0, scrollTop);
61	    this.scrollContainer.setMask(mask);
62	
63	    // 릴리즈 노트 내용 생성
64	    let currentY = 10;
65	
66	    RELEASE_NOTES.forEach((release, index) => {
67	      const isLatest = index === 0;
68	
69	      // 버전 + 날짜 헤더
70	      const versionText = this.add.text(20, currentY, release.version, {
71	        fontSize: '22px',
72	        color: '#FFD700',
73	        fontStyle: 'bold',
74	        stroke: '#000',
75	        strokeThickness: 4,
76	      });
77	      this.scrollContainer.add(versionText);
78	
79	      // NEW 뱃지 (최신 버전만)
80	      if (isLatest) {
81	        const badgeCenterX = versionText.x + versionText.width + 32;
82	        const badgeCenterY = currentY + versionText.height / 2;
83	        const badgeBg = this.add.rectangle(
84	          badgeCenterX, badgeCenterY,
85	          42, 20,
86	          0xff3333, 1,
87	        ).setOrigin(0.5, 0.5);
88	        badgeBg.setStrokeStyle(1, 0xcc0000);
89	        this.scrollContainer.add(badgeBg);
90	
91	        const badgeText = this.add.text(
92	          badgeCenterX, badgeCenterY,
93	          'NEW',
94	          {
95	            fontSize: '12px',
96	            color: '#fff',
97	            fontStyle: 'bold',
98	          },
99	        ).setOrigin(0.5, 0.5);
100	        this.scrollContainer.add(badgeText);
101	      }
102	
103	      const dateText = this.add.text(W - 20, currentY + 5, release.date, {
104	        fontSize: '15px',
105	        color: '#ddd',
106	        fontStyle: 'bold',
107	        stroke: '#000',
108	        strokeThickness: 3,
109	      }).setOrigin(1, 0);
110	      this.scrollContainer.add(dateText);
111	
112	      currentY += 35;
113	
114	      // 구분선
115	      const line = this.add.rectangle(cx, currentY, W - 40, 2, 0xFFD700, 0.4);
116	      this.scrollContainer.add(line);
117	      currentY += 14;
118	
119	      // 변경사항 목록
120	      release.changes.forEach((change) => {
121	        const changeText = this.add.text(35, currentY, `• ${change}`, {
122	          fontSize: '15px',
123	          color: '#fff',
124	          stroke: '#000',
125	          strokeThickness: 3,
126	          wordWrap: { width: W - 60 },
127	        });
128	        this.scrollContainer.add(changeText);
129	        currentY += changeText.height + 10;
130	      });
131	
132	      // 릴리즈 간 여백
133	      if (index < RELEASE_NOTES.length - 1) {
134	        currentY += 20;
135	      }
136	    });
137	
138	    // 하단 여백
139	    currentY += 20;
140	
141	    // 스크롤 가능 범위 계산 (컨텐츠 높이 - 보이는 영역 높이)
142	    this.maxScrollY = Math.max(0, currentY - scrollHeight);
143	
144	    // 스크롤 입력 설정
145	    this.setupScrollInput(scrollTop, scrollBottom);
146	
147	    // 뒤로가기 버튼 (고정)
148	    this.createBackButton(cx, H - 30);
149	  }
150	
151	  private setupScrollInput(scrollTop: number, scrollBottom: number) {
152	    // 터치/마우스 드래그 스크롤
153	    this.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
154	      if (pointer.y > scrollTop && pointer.y < scrollBottom) {
155	        this.isDragging = true;
156	        this.dragStartY = pointer.y;
157	        this.dragStartScrollY = this.scrollY;
158	      }
159	    });
160	
161	    this.input.on('pointermove', (pointer: Phaser.Input.Pointer) => {
162	      if (!this.isDragging) return;
163	      const deltaY = this.dragStartY - pointer.y;
164	      this.scrollY = Phaser.Math.Clamp(
165	        this.dragStartScrollY + deltaY,
166	        0,
167	        this.maxScrollY,
168	      );
169	      this.scrollContainer.y = scrollTop - this.scrollY;
170	    });
171	
172	    this.input.on('pointerup', () => {
173	      this.isDragging = false;
